CREATE OR REPLACE FUNCTION private.accept_swap(p_request_id integer)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_driver int; v_shift int; v_owner int;
begin
  v_driver := my_driver_id();
  if v_driver is null then raise exception 'not_a_driver'; end if;

  select shift_id, requested_by into v_shift, v_owner
  from shift_swap_requests where id = p_request_id and status = 'open' for update;

  if v_shift is null then raise exception 'request_unavailable'; end if;
  if v_owner = v_driver then raise exception 'cannot_accept_own_request'; end if;

  update shift_swap_requests
  set status = 'accepted', accepted_by = v_driver, accepted_at = now()
  where id = p_request_id;

  update shifts set driver_id = v_driver, status = 'swapped' where id = v_shift;

  return json_build_object('ok', true);
end; $function$

CREATE OR REPLACE FUNCTION private.add_customer_address(p_label text, p_compound_id integer, p_unit_number text, p_notes text DEFAULT NULL::text, p_is_default boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_customer_id int; v_new_id int; v_count int;
begin
  v_customer_id := my_customer_id();
  if v_customer_id is null then raise exception 'not_logged_in'; end if;
  if coalesce(trim(p_unit_number), '') = '' then raise exception 'unit_number_required'; end if;

  select count(*) into v_count from customer_addresses where customer_id = v_customer_id;
  if v_count >= 10 then raise exception 'too_many_addresses'; end if;

  if p_is_default or v_count = 0 then
    update customer_addresses set is_default = false where customer_id = v_customer_id;
  end if;

  insert into customer_addresses (customer_id, label, compound_id, unit_number, notes, is_default)
  values (v_customer_id, coalesce(nullif(trim(p_label), ''), 'المنزل'), p_compound_id, trim(p_unit_number), nullif(trim(coalesce(p_notes,'')),''), p_is_default or v_count = 0)
  returning id into v_new_id;

  return v_new_id;
end; $function$

CREATE OR REPLACE FUNCTION private.admin_adjust_order(p_order_id integer, p_amount numeric, p_reason text, p_charge_service_fee boolean DEFAULT false)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor text; v_o orders%rowtype;
  v_pct numeric; v_new_subtotal numeric; v_new_fee numeric; v_waived numeric := null;
  v_new_total numeric; v_has_lines boolean; v_line_id int;
begin
  if is_admin() then v_actor := 'admin';
  elsif is_supervisor() then v_actor := 'supervisor';
  else raise exception 'admin_only';
  end if;

  if p_amount is null or p_amount = 0 then raise exception 'invalid_amount'; end if;
  if coalesce(trim(p_reason), '') = '' then raise exception 'reason_required'; end if;

  select * into v_o from orders where id = p_order_id for update;
  if not found then raise exception 'order_not_found'; end if;
  if v_o.status = 'Cancelled' then raise exception 'order_cancelled'; end if;

  -- PRODUCT lines, not adjustment lines. An order whose only order_items row is
  -- a previous adjustment still has no products to sum.
  select exists (
    select 1 from order_items
     where order_id = p_order_id and not coalesce(is_adjustment, false)
  ) into v_has_lines;

  insert into order_items (order_id, menu_item_id, name, qty, unit_price, total,
                           is_adjustment, created_by)
  values (p_order_id, null, trim(p_reason), 1, p_amount, p_amount, true, v_actor)
  returning id into v_line_id;

  if v_has_lines then
    -- Derived, never assigned: the header cannot disagree with the lines.
    select coalesce(sum(total), 0) into v_new_subtotal
      from order_items where order_id = p_order_id;
  else
    -- Nothing to derive from; apply to what is stored.
    v_new_subtotal := coalesce(v_o.subtotal, 0) + p_amount;
  end if;

  if v_new_subtotal < 0 then raise exception 'negative_subtotal'; end if;

  select coalesce((select value::numeric from settings where key = 'service_fee_percent'), 0)
    into v_pct;

  if p_charge_service_fee then
    v_new_fee := round(v_new_subtotal * v_pct / 100.0);
  else
    v_new_fee := v_o.service_fee;
    v_waived  := round(v_new_subtotal * v_pct / 100.0) - coalesce(v_o.service_fee, 0);
    if v_waived <= 0 then v_waived := null; end if;
    update order_items set service_fee_waived = v_waived where id = v_line_id;
  end if;

  v_new_total := v_new_subtotal + coalesce(v_o.delivery_fee, 0) + coalesce(v_new_fee, 0)
                 - coalesce(v_o.wallet_used, 0);
  if v_new_total < 0 then raise exception 'negative_total'; end if;

  update orders
     set subtotal = v_new_subtotal, service_fee = v_new_fee, total = v_new_total
   where id = p_order_id;

  return json_build_object(
    'order_id',           p_order_id,
    'derived_from_lines', v_has_lines,
    'old_subtotal',       v_o.subtotal,    'new_subtotal',    v_new_subtotal,
    'old_service_fee',    v_o.service_fee, 'new_service_fee', v_new_fee,
    'service_fee_waived', v_waived,
    'delivery_fee',       v_o.delivery_fee,
    'old_total',          v_o.total,       'new_total',       v_new_total,
    'actor',              v_actor
  );
end $function$

CREATE OR REPLACE FUNCTION private.admin_assign_order(p_order_id integer, p_driver_id integer, p_force boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_active boolean; v_attempt int; v_open int; v_declined int; v_status text;
  v_drv_test boolean; v_ord_test boolean;
begin
  if not supervisor_may_touch_order(p_order_id) then raise exception 'admin_only'; end if;

  select status, is_test into v_status, v_ord_test from orders where id = p_order_id for update;
  if v_status is null then raise exception 'order_not_found'; end if;
  if v_status in ('Delivered','Cancelled') then raise exception 'order_closed'; end if;
  if v_status = 'awaiting_payment' then raise exception 'order_not_paid'; end if;

  select active, is_test into v_active, v_drv_test from drivers where id = p_driver_id;
  if v_active is null then raise exception 'driver_not_found'; end if;
  if not v_active then raise exception 'driver_suspended'; end if;

  -- Not even p_force overrides this. Sending a real driver to a test address is
  -- a wasted trip, and putting a test delivery on a real driver is how phantom
  -- cash gets onto his account.
  if v_ord_test is distinct from v_drv_test then raise exception 'not_your_pool'; end if;

  if (select coalesce(pricing_status, 'n/a') from orders where id = p_order_id) = 'pending_quote' then
    raise exception 'order_not_priced';
  end if;

  select count(*) into v_open from delivery_assignments
   where order_id = p_order_id
     and status in ('Offered','Accepted','Picked_Up','Out_for_Delivery');
  if v_open > 0 then raise exception 'already_assigned'; end if;

  select count(*) into v_declined from delivery_assignments
   where order_id = p_order_id and driver_id = p_driver_id
     and status in ('Rejected','Cancelled');
  if v_declined > 0 and not p_force then raise exception 'driver_already_declined'; end if;

  select coalesce(max(attempt_number),0) + 1 into v_attempt
    from delivery_assignments where order_id = p_order_id;

  if v_attempt > 5 and not p_force then raise exception 'too_many_attempts'; end if;

  if not driver_can_take_order(p_driver_id, p_order_id) then
    raise exception 'dispatch_rule_blocked';
  end if;

  insert into delivery_assignments (order_id, driver_id, attempt_number, status, offered_at)
  values (p_order_id, p_driver_id, v_attempt, 'Offered', now());
end $function$

CREATE OR REPLACE FUNCTION private.admin_confirm_cod_deposit(p_order_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_prep int; v_buffer int; v_ready timestamptz; v_dispatch timestamptz; v_slot_id int;
begin
  if not is_admin() then raise exception 'admin_only'; end if;

  select coalesce(r.prep_minutes, 20), o.slot_id into v_prep, v_slot_id
    from orders o join restaurants r on r.id = o.restaurant_id
    where o.id = p_order_id and o.cod_deposit_amount is not null and o.status = 'awaiting_payment';
  if not found then raise exception 'order_not_awaiting_deposit'; end if;

  select coalesce((select value::int from settings where key = 'travel_buffer_minutes'), 10) into v_buffer;

  if v_slot_id is null then
    v_ready := now() + make_interval(mins => v_prep);
    v_dispatch := greatest(now(), v_ready - make_interval(mins => v_buffer));
    update orders set status = 'pending', online_payment_status = 'paid',
      ready_at = v_ready, dispatch_at = v_dispatch
    where id = p_order_id;
  else
    update orders
       set status = case when dispatch_at is not null and dispatch_at > now()
                         then 'Scheduled' else 'pending' end,
           online_payment_status = 'paid'
     where id = p_order_id;
  end if;
end; $function$

CREATE OR REPLACE FUNCTION private.admin_confirm_instapay_payment(p_order_id integer, p_force boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_prep int; v_buffer int; v_ready timestamptz; v_dispatch timestamptz;
        v_slot_id int; v_claimed timestamptz;
begin
  if not is_admin() then raise exception 'admin_only'; end if;

  select coalesce(r.prep_minutes, 20), o.slot_id, o.instapay_claimed_at
    into v_prep, v_slot_id, v_claimed
    from orders o join restaurants r on r.id = o.restaurant_id
    where o.id = p_order_id and o.payment_method = 'instapay' and o.status = 'awaiting_payment';
  if not found then raise exception 'order_not_awaiting_instapay_payment'; end if;

  if v_claimed is null and not p_force then raise exception 'payment_not_claimed'; end if;

  select coalesce((select value::int from settings where key = 'travel_buffer_minutes'), 10) into v_buffer;

  if v_slot_id is null then
    v_ready := now() + make_interval(mins => v_prep);
    v_dispatch := greatest(now(), v_ready - make_interval(mins => v_buffer));
    update orders set status = 'pending', online_payment_status = 'paid',
      ready_at = v_ready, dispatch_at = v_dispatch
    where id = p_order_id;
  else
    update orders
       set status = case when dispatch_at is not null and dispatch_at > now()
                         then 'Scheduled' else 'pending' end,
           online_payment_status = 'paid'
     where id = p_order_id;
  end if;
end $function$

CREATE OR REPLACE FUNCTION private.admin_convert_staff_role(p_profile_id uuid, p_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_current text;
begin
  if not is_admin() then raise exception 'admin_only'; end if;
  if p_role not in ('catalog', 'supervisor') then raise exception 'invalid_role'; end if;
  if p_profile_id = auth.uid() then raise exception 'cannot_target_self'; end if;

  select role into v_current from profiles where id = p_profile_id;
  if v_current is null then raise exception 'profile_not_found'; end if;
  if v_current not in ('catalog', 'supervisor') then raise exception 'target_not_convertible'; end if;

  update profiles set role = p_role where id = p_profile_id;
end $function$

CREATE OR REPLACE FUNCTION private.admin_delete_customer(p_customer_id integer, p_force boolean DEFAULT false)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_phone text; v_auth uuid; v_live int; v_balance numeric; v_orders int;
begin
  if not is_admin() then raise exception 'admin_only'; end if;

  select phone, auth_user_id into v_phone, v_auth from customers where id = p_customer_id;
  if v_phone is null and not exists (select 1 from customers where id = p_customer_id) then
    raise exception 'customer_not_found';
  end if;

  select count(*) into v_live from orders
   where customer_id = p_customer_id
     and status not in ('Delivered','Cancelled','Failed_Delivery');
  if v_live > 0 then raise exception 'customer_has_live_order'; end if;

  select balance into v_balance from customer_wallets where phone = v_phone;
  if coalesce(v_balance, 0) > 0 and not p_force then
    raise exception 'customer_has_wallet_balance:%', v_balance;
  end if;

  select count(*) into v_orders from orders where customer_id = p_customer_id;

  update orders set customer_id = null where customer_id = p_customer_id;
  delete from customer_sessions  where customer_id = p_customer_id;
  delete from customer_addresses where customer_id = p_customer_id;
  if v_phone is not null then delete from customer_otp_codes where phone = v_phone; end if;
  delete from customers          where id = p_customer_id;

  -- The login itself. Without this the person signs in again with Google and a
  -- fresh customer row appears -- which is not a deletion, it is a reset.
  if v_auth is not null then delete from auth.users where id = v_auth; end if;

  return json_build_object('ok', true, 'phone', v_phone,
                           'auth_deleted', v_auth is not null, 'orders_detached', v_orders);
end $function$

CREATE OR REPLACE FUNCTION private.admin_delete_customer_by_phone(p_phone text, p_force boolean DEFAULT false)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
declare v_id int;
begin
  if not is_admin() then raise exception 'admin_only'; end if;
  select id into v_id from customers
   where normalize_phone(phone) = normalize_phone(p_phone) limit 1;
  if v_id is null then raise exception 'no_account_for_phone'; end if;
  return admin_delete_customer(v_id, p_force);
end $function$

CREATE OR REPLACE FUNCTION private.admin_delete_staff(p_profile_id uuid, p_force boolean DEFAULT false)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text; v_driver int; v_cash numeric; v_live int; v_name text;
begin
  if not is_admin() then raise exception 'admin_only'; end if;
  -- An admin deleting their own login locks everyone out of the admin surface,
  -- and there is exactly one admin.
  if p_profile_id = auth.uid() then raise exception 'cannot_delete_self'; end if;

  select role, driver_id, name into v_role, v_driver, v_name from profiles where id = p_profile_id;
  if v_role is null then raise exception 'profile_not_found'; end if;
  if v_role = 'admin' then raise exception 'cannot_delete_admin'; end if;

  if v_driver is not null then
    -- Cash on a rider is a debt to the company. Deleting the login does not
    -- delete the drivers row, but it removes the only way to reach them, and
    -- the settlement screen works off the login.
    select cash_held into v_cash from drivers where id = v_driver;
    if coalesce(v_cash, 0) > 0 and not p_force then
      raise exception 'driver_holds_cash:%', v_cash;
    end if;
    select count(*) into v_live from delivery_assignments
     where driver_id = v_driver and status in ('Offered','Accepted','Picked_Up','Out_for_Delivery');
    if v_live > 0 then raise exception 'driver_has_live_delivery'; end if;
  end if;

  delete from push_tokens where profile_id = p_profile_id;
  -- profiles.id cascades from auth.users, so this takes the profile with it.
  delete from auth.users where id = p_profile_id;

  -- The drivers / restaurants row is deliberately left alone: it carries the
  -- earnings, the ratings and the order history. Removing a login removes
  -- access, not the record of what that person did.
  return json_build_object('ok', true, 'role', v_role, 'name', v_name,
                           'driver_id', v_driver, 'driver_row_kept', v_driver is not null);
end $function$

CREATE OR REPLACE FUNCTION private.admin_force_delivered(p_order_id integer, p_reason text, p_cash_collected boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_assignment_id int; v_driver int; v_status text;
  v_total numeric; v_fee numeric; v_payment_method text; v_cod_deposit numeric;
  v_cash_due numeric; v_driver_earning numeric; v_is_test boolean;
begin
  if not supervisor_may_touch_order(p_order_id) then raise exception 'admin_only'; end if;
  if coalesce(trim(p_reason), '') = '' then raise exception 'reason_required'; end if;

  select status into v_status from orders where id = p_order_id for update;
  if v_status is null then raise exception 'order_not_found'; end if;
  if v_status = 'Delivered' then return; end if;
  if v_status = 'Cancelled' then raise exception 'order_closed'; end if;

  select id, driver_id into v_assignment_id, v_driver
    from delivery_assignments
   where order_id = p_order_id and status in ('Accepted','Picked_Up','Out_for_Delivery')
   order by attempt_number desc limit 1;
  if v_assignment_id is null then raise exception 'no_active_assignment'; end if;

  select total, delivery_fee, payment_method, cod_deposit_amount, is_test
    into v_total, v_fee, v_payment_method, v_cod_deposit, v_is_test
    from orders where id = p_order_id;

  v_cash_due := case
    when v_payment_method = 'instapay' then 0
    when v_cod_deposit is not null then v_total - v_cod_deposit
    else v_total
  end;
  if not p_cash_collected then v_cash_due := 0; end if;

  update delivery_assignments
     set status = 'Delivered', delivered_at = now(),
         cash_confirmed_at = case when v_cash_due > 0 then coalesce(cash_confirmed_at, now()) else cash_confirmed_at end
   where id = v_assignment_id;

  update orders
     set status = 'Delivered',
         cancel_reason = coalesce(nullif(trim(cancel_reason), ''), 'أُغلق بواسطة الإدارة: ' || trim(p_reason))
   where id = p_order_id;

  if v_is_test then
    update drivers set status = 'Available', available = true where id = v_driver;
    return;
  end if;

  v_fee := coalesce(v_fee, 65);
  select coalesce((select value::numeric from settings where key = 'driver_flat_earning_egp'), 10)
    into v_driver_earning;
  v_driver_earning := least(greatest(v_driver_earning, 0), v_fee);

  insert into driver_earnings (driver_id, order_id, assignment_id, delivery_fee, driver_earning, admin_amount)
  values (v_driver, p_order_id, v_assignment_id, v_fee, v_driver_earning, v_fee - v_driver_earning)
  on conflict (assignment_id) do nothing;

  update drivers set
    status           = 'Available',
    available        = true,
    total_deliveries = coalesce(total_deliveries, 0) + 1,
    cash_held        = coalesce(cash_held, 0) + greatest(coalesce(v_cash_due, 0), 0)
  where id = v_driver;
end $function$

CREATE OR REPLACE FUNCTION private.admin_reassign_order(p_order_id integer, p_driver_id integer, p_reason text DEFAULT 'admin_reassigned'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
begin
  -- Admin, or a supervisor acting on a catalog restaurant order.
  if not supervisor_may_touch_order(p_order_id) then raise exception 'admin_only'; end if;
  perform admin_unassign_order(p_order_id, p_reason);
  perform admin_assign_order(p_order_id, p_driver_id);
end;
$function$

CREATE OR REPLACE FUNCTION private.admin_resolve_no_answer(p_assignment_id integer, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'private', 'public'
AS $function$
declare v_order_id int;
begin
  -- Admin, or a supervisor acting on a catalog restaurant order.
  if not supervisor_may_touch_order((select order_id from delivery_assignments where id = p_assignment_id)) then raise exception 'admin_only'; end if;
  if p_action not in ('wait','contact','fail','refund','cancel') then
    raise exception 'invalid_action';
  end if;

  select order_id into v_order_id from delivery_assignments where id = p_assignment_id;
  if v_order_id is null then raise exception 'assignment_not_found'; end if;

  if p_action in ('fail','cancel') then
    perform mark_delivery_failed(p_assignment_id);
  elsif p_action = 'refund' then
    perform cancel_order(v_order_id, 'تعذّر التوصيل — تم الإلغاء والاسترداد', null);
  end if;

  update delivery_assignments
     set no_answer_admin_action = p_action,
         no_answer_reported_at  = case when p_action = 'wait' then null else no_answer_reported_at end,
         called_customer_at     = case when p_action = 'wait' then null else called_customer_at end,
         delivery_problem_reason = case when p_action = 'wait' then null else delivery_problem_reason end
   where id = p_assignment_id;
end $function$

CREATE OR REPLACE FUNCTION private.admin_set_customer_ban(p_phone text, p_banned boolean, p_reason text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_phone text; v_open int;
begin
  if not is_admin() then raise exception 'admin_only'; end if;
  v_phone := normalize_phone(p_phone);
  if coalesce(v_phone, '') = '' then raise exception 'invalid_phone'; end if;

  if p_banned then
    -- Refuse while they have work in flight. Banning someone mid-delivery
    -- leaves a driver holding food for an order the system now disowns, and
    -- the right sequence is to settle the live order first.
    select count(*) into v_open from orders
     where normalize_phone(customer_phone) = v_phone
       and status not in ('Delivered', 'Cancelled', 'Failed');
    if v_open > 0 then raise exception 'has_live_orders'; end if;

    insert into banned_customers (phone, reason, banned_by)
    values (v_phone, nullif(btrim(coalesce(p_reason, '')), ''), auth.uid())
    on conflict (phone) do update
      set reason = excluded.reason, banned_at = now(), banned_by = excluded.banned_by;
  else
    delete from banned_customers where phone = v_phone;
  end if;

  return json_build_object('phone', v_phone, 'banned', p_banned);
end $function$

CREATE OR REPLACE FUNCTION private.admin_set_vendor_slots(p_restaurant_id integer, p_enabled boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not is_admin() then raise exception 'admin_only'; end if;
  update restaurants set uses_delivery_slots = coalesce(p_enabled, false)
   where id = p_restaurant_id;
  if not found then raise exception 'vendor_not_found'; end if;
  return coalesce(p_enabled, false);
end $function$

CREATE OR REPLACE FUNCTION private.admin_upsert_driver(p_id integer, p_name text, p_phone text, p_vehicle_type text DEFAULT 'motorcycle'::text, p_vehicle_plate text DEFAULT ''::text, p_instapay_number text DEFAULT NULL::text, p_payout_schedule text DEFAULT 'daily'::text, p_active boolean DEFAULT true)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id int;
begin
  if not is_admin() then raise exception 'admin_only'; end if;
  if coalesce(trim(p_name), '') = '' then raise exception 'name_required'; end if;
  if coalesce(trim(p_phone), '') = '' then raise exception 'phone_required'; end if;
  if p_vehicle_type not in ('motorcycle','van') then raise exception 'invalid_vehicle_type'; end if;
  if p_payout_schedule not in ('daily','weekly') then raise exception 'invalid_payout_schedule'; end if;

  -- Two drivers on one number means dispatch phones the wrong person and the
  -- cash lands on the wrong ledger.
  if exists (select 1 from drivers d where normalize_phone(d.phone) = normalize_phone(p_phone)
               and (p_id is null or d.id <> p_id)) then
    raise exception 'phone_already_used';
  end if;

  if p_id is null then
    insert into drivers (name, phone, vehicle_type, vehicle_plate, instapay_number, payout_schedule, active)
    values (trim(p_name), trim(p_phone), p_vehicle_type, coalesce(p_vehicle_plate,''),
            nullif(trim(coalesce(p_instapay_number,'')),''), p_payout_schedule, coalesce(p_active, true))
    returning id into v_id;
  else
    -- cash_held, rating, total_deliveries and the device binding are NOT
    -- editable here. They are earned or bound by the system; a form that can
    -- silently zero a rider's outstanding cash is a form that will.
    update drivers
       set name = trim(p_name), phone = trim(p_phone), vehicle_type = p_vehicle_type,
           vehicle_plate = coalesce(p_vehicle_plate,''),
           instapay_number = nullif(trim(coalesce(p_instapay_number,'')),''),
           payout_schedule = p_payout_schedule, active = coalesce(p_active, true)
     where id = p_id
     returning id into v_id;
    if v_id is null then raise exception 'driver_not_found'; end if;
    -- Keep profiles.name in step; the admin accounts list reads it and the two
    -- have been observed disagreeing for every real driver.
    update profiles set name = trim(p_name) where driver_id = v_id and role = 'driver';
  end if;

  return json_build_object('id', v_id, 'created', p_id is null);
end $function$

CREATE OR REPLACE FUNCTION private.append_request_items_secure(p_token uuid, p_items json, p_rate_key text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_bucket text;
  v_recent integer;
  v_o orders%rowtype;
  v_merged jsonb;
  v_new jsonb;
  v_item jsonb;
  v_idx integer;
  v_name text;
begin
  if p_token is null then raise exception 'invalid_token'; end if;
  if p_rate_key is null or p_rate_key !~ '^[0-9a-f]{64}$' then raise exception 'invalid_rate_key'; end if;
  if p_items is null or json_typeof(p_items) <> 'array' then raise exception 'invalid_items'; end if;
  if json_array_length(p_items) not between 1 and 20 then raise exception 'invalid_item_count'; end if;
  if exists (
    select 1 from json_array_elements(p_items) item
     where json_typeof(item) <> 'object'
        or length(btrim(coalesce(item->>'name', ''))) not between 1 and 200
        or not case
          when length(coalesce(item->>'qty', '')) <= 3
               and coalesce(item->>'qty', '') ~ '^[0-9]+$'
          then (item->>'qty')::numeric between 1 and 100
          else false
        end
  ) then raise exception 'invalid_item'; end if;

  v_bucket := 'order-edit-sha256:' || p_rate_key;
  perform pg_advisory_xact_lock(hashtextextended(v_bucket, 0));
  select count(*) into v_recent from rate_limit_log
   where bucket = v_bucket and called_at > now() - interval '15 minutes';
  if v_recent >= 5 then raise exception 'order_edit_rate_limit'; end if;
  select count(*) into v_recent from rate_limit_log
   where bucket = v_bucket and called_at > now() - interval '24 hours';
  if v_recent >= 20 then raise exception 'daily_order_edit_limit'; end if;

  select * into v_o from orders where public_token = p_token for update;
  if not found then raise exception 'order_not_found'; end if;
  if v_o.status in ('Cancelled','Failed','Delivered') then raise exception 'order_closed'; end if;
  if coalesce(v_o.pricing_status,'n/a') <> 'pending_quote' then raise exception 'order_not_priced'; end if;
  if coalesce(v_o.kitchen_status,'new') <> 'new' then raise exception 'wrong_stage'; end if;
  if exists (select 1 from delivery_assignments da
              where da.order_id = v_o.id
                and da.status in ('Offered','Accepted','Picked_Up','Out_for_Delivery')) then
    raise exception 'already_assigned';
  end if;

  v_merged := coalesce(v_o.request_items, '[]'::jsonb);
  v_new := p_items::jsonb;
  for v_item in select * from jsonb_array_elements(v_new) loop
    v_name := lower(btrim(v_item->>'name'));
    v_idx := null;
    select i - 1 into v_idx
      from generate_series(1, jsonb_array_length(v_merged)) i
     where lower(btrim(coalesce(v_merged->(i-1)->>'name',''))) = v_name
     limit 1;

    if v_idx is null then
      v_merged := v_merged || jsonb_build_array(
        jsonb_build_object('name', btrim(v_item->>'name'), 'qty', (v_item->>'qty')::integer));
    else
      v_merged := jsonb_set(v_merged, array[v_idx::text, 'qty'],
        to_jsonb(coalesce((v_merged->v_idx->>'qty')::integer, 1) + (v_item->>'qty')::integer));
    end if;
  end loop;

  if jsonb_typeof(v_merged) <> 'array' or jsonb_array_length(v_merged) > 50 then
    raise exception 'too_many_order_items';
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_merged) item
     where length(btrim(coalesce(item->>'name', ''))) not between 1 and 200
        or not case
          when length(coalesce(item->>'qty', '')) <= 3
               and coalesce(item->>'qty', '') ~ '^[0-9]+$'
          then (item->>'qty')::numeric between 1 and 100
          else false
        end
  ) then raise exception 'invalid_merged_item'; end if;

  update orders set request_items = v_merged where id = v_o.id;
  insert into rate_limit_log (bucket) values (v_bucket);
  return json_build_object('items', v_merged);
end
$function$

CREATE OR REPLACE FUNCTION private.cancel_order(p_order_id integer, p_reason text DEFAULT ''::text, p_token uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_status text; v_kitchen text; v_public_token uuid; v_restaurant_id int;
  v_driver_id int; v_active_count int;
  v_wallet_used numeric; v_customer_phone text; v_wallet_id int;
  v_payment_method text; v_online_status text; v_instapay_claimed boolean; v_total numeric;
  v_cod_deposit numeric; v_is_vendor boolean; v_is_admin boolean; v_reason text;
begin
  select status, kitchen_status, public_token, restaurant_id, wallet_used, customer_phone,
         payment_method, online_payment_status, instapay_claimed_at is not null, total, cod_deposit_amount
    into v_status, v_kitchen, v_public_token, v_restaurant_id, v_wallet_used, v_customer_phone,
         v_payment_method, v_online_status, v_instapay_claimed, v_total, v_cod_deposit
    from orders where id = p_order_id for update;
  if v_status is null then raise exception 'order_not_found'; end if;

  v_is_admin  := is_admin() or supervisor_may_touch_order(p_order_id);
  v_is_vendor := my_restaurant_id() is not null and my_restaurant_id() = v_restaurant_id;

  if not (
    (p_token is not null and p_token = v_public_token)
    or v_is_vendor
    or v_is_admin
  ) then
    raise exception 'not_authorized';
  end if;

  if v_status in ('Delivered','Cancelled') then raise exception 'order_closed'; end if;

  if not v_is_admin and not v_is_vendor then
    if not is_customer_cancellable_status(v_status) then
      raise exception 'too_late_to_cancel';
    end if;
    if coalesce(v_kitchen, 'new') <> 'new' then
      raise exception 'too_late_to_cancel';
    end if;
  elsif v_is_vendor and not v_is_admin then
    if v_status not in ('pending','awaiting_payment','awaiting_quote','Scheduled','Driver_Searching','No_Driver_Found') then
      raise exception 'too_late_to_cancel';
    end if;
  end if;

  v_reason := nullif(trim(coalesce(p_reason, '')), '');
  if not v_is_admin and not v_is_vendor
     and v_reason not in (
       'customer_waiting_too_long',
       'customer_price_too_high',
       'customer_payment_problem',
       'customer_ordered_by_mistake',
       'customer_changed_mind',
       'customer_other'
     ) then
    v_reason := 'customer_other';
  end if;

  update orders set status = 'Cancelled',
    cancel_reason = v_reason,
    cancelled_at  = now(),
    refund_status = case
      when v_payment_method in ('instapay','online')
           and (v_instapay_claimed or v_online_status = 'paid')
           and v_total > 0
      then 'pending'
      when v_payment_method = 'cod' and v_cod_deposit is not null
           and (v_instapay_claimed or v_online_status = 'paid')
      then 'pending'
      else refund_status
    end
  where id = p_order_id;

  if v_wallet_used is not null and v_wallet_used > 0 then
    select id into v_wallet_id from customer_wallets where phone = normalize_phone(v_customer_phone) for update;
    if v_wallet_id is not null then
      update customer_wallets set balance = balance + v_wallet_used where id = v_wallet_id;
      insert into wallet_transactions (wallet_id, amount, reason, order_id)
        values (v_wallet_id, v_wallet_used, 'استرداد بسبب إلغاء الطلب #' || p_order_id, p_order_id);
    end if;
  end if;

  select driver_id into v_driver_id from delivery_assignments
    where order_id = p_order_id and status in ('Offered','Accepted','Picked_Up','Out_for_Delivery')
    limit 1;

  update delivery_assignments set status = 'Cancelled',
    rejection_reason = coalesce(v_reason, 'order_cancelled')
  where order_id = p_order_id and status in ('Offered','Accepted','Picked_Up','Out_for_Delivery');

  if v_driver_id is not null then
    select count(*) into v_active_count from delivery_assignments
      where driver_id = v_driver_id and status in ('Accepted','Picked_Up','Out_for_Delivery');
    update drivers set available = (v_active_count < 3),
      status = case when v_active_count = 0 then 'Available' else status end
    where id = v_driver_id;
  end if;
end $function$

CREATE OR REPLACE FUNCTION private.confirm_custom_order_price(p_order_id integer, p_subtotal numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_o orders%rowtype; v_total numeric; v_threshold numeric; v_deposit numeric;
        v_status text; v_pct numeric; v_service numeric;
begin
  if not is_supervisor() then raise exception 'not_authorized'; end if;
  if p_subtotal is null or p_subtotal < 0 then raise exception 'invalid_amount'; end if;

  select * into v_o from orders where id = p_order_id and order_type = 'custom_request';
  if not found then raise exception 'order_not_found'; end if;
  if v_o.status = 'Cancelled' then raise exception 'order_closed'; end if;

  -- Same source, same base (subtotal only) and same rounding as place_order, so
  -- a supermarket run and a catalogue basket of equal value cost the customer
  -- the same. Deliberately computed BEFORE the deposit, because the deposit is
  -- half of what the customer actually owes.
  select coalesce((select value::numeric from settings where key = 'service_fee_percent'), 0) into v_pct;
  v_service := round(p_subtotal * v_pct / 100.0);
  v_total := p_subtotal + v_o.delivery_fee + v_service;

  v_deposit := null;
  if v_o.payment_method = 'cod' then
    select coalesce((select value::numeric from settings where key = 'cod_deposit_threshold_egp'), 300)
      into v_threshold;
    if v_total > v_threshold then v_deposit := ceil(v_total * 0.5); end if;
  end if;

  v_status := case
    when v_deposit is not null then 'awaiting_payment'
    when v_o.status = 'awaiting_quote' then
      -- 'Scheduled' only if the customer actually booked a slot. A non-slot
      -- custom order with a future dispatch_at is an ASAP order mid-prep.
      case when v_o.slot_id is not null and coalesce(v_o.dispatch_at, v_o.created_at) > now()
           then 'Scheduled' else 'pending' end
    else v_o.status
  end;

  update orders
     set subtotal = p_subtotal,
         service_fee = v_service,
         total = v_total,
         pricing_status = 'confirmed',
         cod_deposit_amount = v_deposit,
         online_payment_status = case when v_deposit is not null then 'pending' else online_payment_status end,
         status = v_status
   where id = p_order_id;
end $function$

CREATE OR REPLACE FUNCTION private.credit_wallet(p_phone text, p_amount numeric, p_reason text, p_order_id integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_wallet_id integer;
  v_phone text;
  v_reason text;
begin
  if not is_admin() then raise exception 'admin_only'; end if;

  v_phone := normalize_phone(p_phone);
  v_reason := nullif(btrim(coalesce(p_reason, '')), '');

  if coalesce(v_phone, '') = '' then raise exception 'invalid_phone'; end if;
  if p_amount is null or p_amount = 'NaN'::numeric or p_amount <= 0 then
    raise exception 'invalid_credit_amount';
  end if;
  if v_reason is null then raise exception 'reason_required'; end if;
  if length(v_reason) > 500 then raise exception 'reason_too_long'; end if;
  if p_order_id is not null
     and not exists (select 1 from orders where id = p_order_id) then
    raise exception 'order_not_found';
  end if;

  insert into customer_wallets (phone, balance) values (v_phone, 0)
  on conflict (phone) do nothing;

  select id into v_wallet_id
    from customer_wallets
   where phone = v_phone
   for update;

  update customer_wallets
     set balance = balance + p_amount
   where id = v_wallet_id;

  insert into wallet_transactions (wallet_id, amount, reason, order_id)
  values (v_wallet_id, p_amount, v_reason, p_order_id);
end;
$function$

CREATE OR REPLACE FUNCTION private.delete_customer_address(p_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_customer_id int; v_was_default boolean;
begin
  v_customer_id := my_customer_id();
  if not exists (select 1 from customer_addresses where id = p_id and customer_id = v_customer_id) then
    raise exception 'not_your_address';
  end if;

  select is_default into v_was_default from customer_addresses where id = p_id;
  delete from customer_addresses where id = p_id;

  if v_was_default then
    update customer_addresses set is_default = true
    where id = (select id from customer_addresses where customer_id = v_customer_id order by id limit 1);
  end if;
end; $function$

CREATE OR REPLACE FUNCTION private.escalate_swap(p_request_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_driver int;
begin
  v_driver := my_driver_id();
  if v_driver is null then raise exception 'not_a_driver'; end if;

  if not exists (select 1 from shift_swap_requests
                 where id = p_request_id and requested_by = v_driver and status = 'open') then
    raise exception 'not_your_request';
  end if;

  update shift_swap_requests set status = 'escalated', escalated_at = now()
  where id = p_request_id;
end; $function$

CREATE OR REPLACE FUNCTION private.log_app_event(p_event text, p_device_id text DEFAULT NULL::text, p_session_id uuid DEFAULT NULL::uuid, p_compound_id integer DEFAULT NULL::integer, p_restaurant_id integer DEFAULT NULL::integer, p_order_id integer DEFAULT NULL::integer, p_props jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_recent int;
begin
  if p_event not in (
    'arrival', 'place_chosen', 'vendor_opened', 'item_added',
    'customization_opened', 'customization_abandoned',
    'checkout_started', 'checkout_blocked', 'order_placed'
  ) then
    return;
  end if;

  if p_device_id is not null then
    select count(*) into v_recent
    from app_events
    where device_id = p_device_id
      and created_at > now() - interval '1 minute';
    if v_recent >= 120 then return; end if;
  end if;

  insert into app_events (
    event, device_id, session_id, customer_id,
    compound_id, restaurant_id, order_id, props
  )
  values (
    p_event, left(coalesce(p_device_id, ''), 64), p_session_id, my_customer_id(),
    p_compound_id, p_restaurant_id, p_order_id,
    case
      when length(p_props::text) > 2000 then '{"truncated":true}'::jsonb
      else coalesce(p_props, '{}'::jsonb)
    end
  );
end
$function$

CREATE OR REPLACE FUNCTION private.mark_delivery_failed(p_assignment_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_order_id int; v_driver int; v_active_count int; v_fee numeric; v_earn numeric;
begin
  -- Admin, or a supervisor acting on a catalog restaurant order.
  if not supervisor_may_touch_order((select order_id from delivery_assignments where id = p_assignment_id)) then raise exception 'admin_only'; end if;

  select order_id, driver_id into v_order_id, v_driver
  from delivery_assignments where id = p_assignment_id for update;
  if v_driver is null then raise exception 'assignment_not_found'; end if;

  select coalesce(delivery_fee, 50) into v_fee from orders where id = v_order_id;

  -- Same setting mark_delivered uses. Hardcoding 10 here meant a failed
  -- delivery paid more than a successful one under the salary model.
  select coalesce((select value::numeric from settings where key = 'driver_flat_earning_egp'), 10)
    into v_earn;
  v_earn := least(greatest(v_earn, 0), v_fee);

  update delivery_assignments set status = 'Failed' where id = p_assignment_id;
  update orders set status = 'Failed_Delivery' where id = v_order_id;

  insert into driver_earnings (driver_id, order_id, assignment_id, delivery_fee, driver_earning, admin_amount)
  values (v_driver, v_order_id, p_assignment_id, v_fee, v_earn, v_fee - v_earn)
  on conflict (assignment_id) do nothing;

  select count(*) into v_active_count from delivery_assignments
    where driver_id = v_driver and status in ('Accepted','Picked_Up','Out_for_Delivery');

  update drivers set status = case when v_active_count = 0 then 'Available' else status end,
    available = (v_active_count < 3)
  where id = v_driver;
end; $function$

CREATE OR REPLACE FUNCTION private.mark_instapay_claimed(p_token uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order_id integer;
  v_claimed_at timestamptz;
begin
  select id, instapay_claimed_at into v_order_id, v_claimed_at
    from orders
   where public_token = p_token
     and status = 'awaiting_payment'
     and (
       payment_method = 'instapay'
       or (payment_method = 'cod' and cod_deposit_amount is not null)
     )
   for update;

  if not found then raise exception 'order_not_awaiting_payment'; end if;
  if v_claimed_at is not null then return; end if;

  update orders set instapay_claimed_at = now() where id = v_order_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.mark_refunded(p_order_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_status text;
begin
  if not is_admin() then raise exception 'admin_only'; end if;

  select refund_status into v_status
    from orders
   where id = p_order_id
   for update;

  if not found then raise exception 'order_not_found'; end if;
  if v_status is distinct from 'pending' then
    raise exception 'refund_not_pending';
  end if;

  update orders set refund_status = 'refunded' where id = p_order_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.place_order(p_restaurant_id integer, p_customer_name text, p_customer_phone text, p_zone text, p_unit_number text, p_address_notes text, p_delivery_fee numeric, p_items json, p_slot_id integer DEFAULT NULL::integer, p_scheduled_date date DEFAULT NULL::date, p_compound_id integer DEFAULT NULL::integer, p_payment_method text DEFAULT 'cod'::text, p_use_wallet boolean DEFAULT false, p_session_token uuid DEFAULT NULL::uuid, p_customer_note text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order_id int; v_token uuid; v_subtotal numeric := 0; v_item json;
  v_prep int; v_buffer int; v_ready timestamptz; v_dispatch timestamptz;
  v_slot delivery_slots%rowtype; v_used int; v_open boolean; v_req boolean;
  v_fee numeric; v_km numeric; v_status text; v_sla int;
  v_service_fee_pct numeric; v_service_fee numeric;
  v_wallet_id int; v_wallet_balance numeric := 0; v_wallet_used numeric := 0;
  v_total numeric;
  v_menu_item_id int; v_qty int; v_real_price numeric; v_real_name text; v_available boolean; v_category text;
  v_customer_id int; v_session_phone text; v_require_login text;
  v_size_id int; v_has_sizes boolean; v_size_price numeric; v_size_name text; v_item_unit_price numeric;
  v_combo_id int; v_combo_price numeric; v_combo_name text;
  v_addon_ids int[]; v_addon_total numeric; v_addon_names text[]; v_matched_count int;
  v_group menu_item_addon_groups%rowtype; v_group_count int;
  v_lines jsonb := '[]'::jsonb; v_line jsonb;
  v_avail_from time; v_avail_until time; v_cairo_now time;
  v_item_disc discounts%rowtype; v_cat_disc discounts%rowtype;
  v_base_price numeric; v_original_unit_price numeric;
  v_cod_threshold numeric; v_cod_deposit numeric; v_net_total numeric;
begin
  if coalesce(trim(p_customer_name),'') = '' or coalesce(trim(p_customer_phone),'') = ''
     or coalesce(trim(p_zone),'') = '' or coalesce(trim(p_unit_number),'') = '' then
    raise exception 'missing_customer_details';
  end if;
  -- A ban is enforced where the order is CREATED, not where the button is
  -- drawn. Hiding a control in the UI stops nobody who reloads the page.
  if is_banned(p_customer_phone) then
    raise exception 'account_blocked';
  end if;
  if p_payment_method not in ('cod','online','instapay') then raise exception 'invalid_payment_method'; end if;

  if p_session_token is not null then
    select cs.customer_id, c.phone into v_customer_id, v_session_phone
      from customer_sessions cs join customers c on c.id = cs.customer_id
      where cs.token = p_session_token and cs.expires_at > now();
  end if;

  if v_customer_id is null then
    v_customer_id := my_customer_id();
  end if;

  -- A Google or email customer has no legacy session row, so v_session_phone
  -- stayed null and the wallet guard below could never match -- while
  -- wallet_balance_for_phone happily showed them a balance to spend.
  if v_session_phone is null and v_customer_id is not null then
    select phone into v_session_phone from customers where id = v_customer_id;
  end if;

  select value into v_require_login from settings where key = 'require_customer_login';
  if coalesce(v_require_login, 'false') = 'true' and v_customer_id is null then
    raise exception 'login_required';
  end if;

  select vendor_is_open_now(p_restaurant_id) into v_open;
  if not found or not v_open then raise exception 'restaurant_closed'; end if;

  if p_compound_id is not null and not vendor_covers_compound(p_restaurant_id, p_compound_id) then
    raise exception 'vendor_not_covering_compound';
  end if;

  if p_compound_id is null then raise exception 'compound_id_required'; end if;
  select distance_km, delivery_fee into v_km, v_fee from compounds where id = p_compound_id;
  if v_km is null then raise exception 'compound_missing_distance'; end if;
  if v_fee is null then raise exception 'compound_missing_fee'; end if;
  v_sla := sla_minutes_for(p_restaurant_id, p_compound_id);

  if json_array_length(p_items) = 0 then raise exception 'empty_order'; end if;

  v_cairo_now := (now() at time zone 'Africa/Cairo')::time;

  for v_item in select * from json_array_elements(p_items) loop
    v_menu_item_id := (v_item->>'menu_item_id')::int;
    v_qty := (v_item->>'qty')::int;
    v_size_id := nullif(v_item->>'size_id','')::int;
    v_combo_id := nullif(v_item->>'combo_id','')::int;
    if v_menu_item_id is null or v_qty is null or v_qty <= 0 then raise exception 'invalid_item'; end if;

    select price, name, available, available_from, available_until, category
      into v_real_price, v_real_name, v_available, v_avail_from, v_avail_until, v_category
      from menu_items where id = v_menu_item_id and restaurant_id = p_restaurant_id;
    if v_real_price is null then raise exception 'menu_item_not_found'; end if;
    if not coalesce(v_available, true) then raise exception 'item_unavailable'; end if;
    if v_avail_from is not null and v_avail_until is not null and v_cairo_now not between v_avail_from and v_avail_until then
      raise exception 'item_not_available_now';
    end if;
    select coalesce(requires_prescription, false) into v_req from menu_items where id = v_menu_item_id;

    select exists(select 1 from menu_item_sizes where menu_item_id = v_menu_item_id and available) into v_has_sizes;
    v_size_name := null;
    v_combo_name := null;

    -- A combo is a REPLACEMENT price for a different product (sandwich + fries
    -- + drink), not a surcharge, and it stands in for the size choice: the
    -- combo rows ARE عادي/وسط/كبير. So it is resolved first and, when present,
    -- the size requirement does not apply. The price is read from the table,
    -- never from the client -- same rule as sizes and add-ons.
    if v_combo_id is not null then
      select price, name into v_combo_price, v_combo_name from menu_item_combos
        where id = v_combo_id and menu_item_id = v_menu_item_id and available;
      if v_combo_price is null then raise exception 'invalid_combo'; end if;
      v_base_price := v_combo_price;
    elsif v_has_sizes then
      if v_size_id is null then raise exception 'size_required'; end if;
      select price, name into v_size_price, v_size_name from menu_item_sizes
        where id = v_size_id and menu_item_id = v_menu_item_id and available;
      if v_size_price is null then raise exception 'invalid_size'; end if;
      v_base_price := v_size_price;
    else
      v_base_price := v_real_price;
    end if;

    select * into v_item_disc from discounts
      where scope = 'item' and menu_item_id = v_menu_item_id and active
        and (starts_at is null or now() >= starts_at) and (ends_at is null or now() <= ends_at)
      limit 1;
    select * into v_cat_disc from discounts
      where scope = 'category' and restaurant_id = p_restaurant_id and category = v_category and active
        and (starts_at is null or now() >= starts_at) and (ends_at is null or now() <= ends_at)
      limit 1;

    v_original_unit_price := v_base_price;
    if v_item_disc.id is not null then
      v_base_price := case when v_item_disc.discount_type = 'percent'
        then round(v_base_price * (1 - v_item_disc.value / 100.0), 2)
        else greatest(0, v_base_price - v_item_disc.value) end;
    elsif v_cat_disc.id is not null then
      v_base_price := case when v_cat_disc.discount_type = 'percent'
        then round(v_base_price * (1 - v_cat_disc.value / 100.0), 2)
        else greatest(0, v_base_price - v_cat_disc.value) end;
    end if;
    v_item_unit_price := v_base_price;

    select array(select (jsonb_array_elements_text(coalesce(v_item::jsonb->'addon_ids', '[]'::jsonb)))::int)
      into v_addon_ids;
    v_addon_total := 0; v_addon_names := array[]::text[];
    if v_addon_ids is not null and array_length(v_addon_ids, 1) > 0 then
      select coalesce(sum(a.price), 0), coalesce(array_agg(a.name order by a.display_order), array[]::text[]),
             count(*)
        into v_addon_total, v_addon_names, v_matched_count
      from menu_item_addons a join menu_item_addon_groups g on g.id = a.group_id
      where a.id = any(v_addon_ids) and g.menu_item_id = v_menu_item_id and a.available;
      if v_matched_count <> array_length(v_addon_ids, 1) then raise exception 'invalid_addon'; end if;

      for v_group in select * from menu_item_addon_groups where menu_item_id = v_menu_item_id loop
        select count(*) into v_group_count from menu_item_addons a
          where a.group_id = v_group.id and a.id = any(v_addon_ids);
        if v_group_count < v_group.min_select then raise exception 'addon_group_min_not_met'; end if;
        if v_group.max_select is not null and v_group_count > v_group.max_select then
          raise exception 'addon_group_max_exceeded';
        end if;
      end loop;
    else
      for v_group in select * from menu_item_addon_groups where menu_item_id = v_menu_item_id loop
        if v_group.min_select > 0 then raise exception 'addon_group_min_not_met'; end if;
      end loop;
    end if;

    v_item_unit_price := v_item_unit_price + v_addon_total;
    v_subtotal := v_subtotal + (v_qty * v_item_unit_price);

    v_line := jsonb_build_object(
      'menu_item_id', v_menu_item_id, 'qty', v_qty, 'unit_price', v_item_unit_price,
      'name', v_real_name, 'requires_prescription', coalesce(v_req, false),
      'size_name', v_size_name, 'combo_name', v_combo_name, 'addon_names', to_jsonb(v_addon_names),
      'original_unit_price', case when v_original_unit_price <> v_base_price then v_original_unit_price + v_addon_total else null end
    );
    v_lines := v_lines || jsonb_build_array(v_line);
  end loop;

  select coalesce((select value::numeric from settings where key = 'service_fee_percent'), 0)
    into v_service_fee_pct;
  v_service_fee := round(v_subtotal * v_service_fee_pct / 100.0);
  v_total := v_subtotal + v_fee + v_service_fee;

  if p_use_wallet and v_session_phone is not null
     and normalize_phone(v_session_phone) = normalize_phone(p_customer_phone) then
    insert into customer_wallets (phone, balance) values (normalize_phone(p_customer_phone), 0)
      on conflict (phone) do nothing;
    select id, balance into v_wallet_id, v_wallet_balance
      from customer_wallets where phone = normalize_phone(p_customer_phone) for update;
    v_wallet_used := least(coalesce(v_wallet_balance, 0), v_total);
  end if;

  v_net_total := v_total - v_wallet_used;

  v_cod_deposit := null;
  if p_payment_method = 'cod' then
    select coalesce((select value::numeric from settings where key = 'cod_deposit_threshold_egp'), 300)
      into v_cod_threshold;
    if v_net_total > v_cod_threshold then
      v_cod_deposit := ceil(v_net_total * 0.5);
    end if;
  end if;

  select coalesce(prep_minutes, 20) into v_prep from restaurants where id = p_restaurant_id;
  select coalesce((select value::int from settings where key = 'travel_buffer_minutes'), 10)
    into v_buffer;

  if p_slot_id is not null then
    select * into v_slot from delivery_slots where id = p_slot_id for update;
    if not found or not v_slot.active then raise exception 'slot_unavailable'; end if;

    select count(*) into v_used from orders
      where slot_id = p_slot_id and scheduled_date = p_scheduled_date
        and status <> 'Cancelled';
    if v_used >= v_slot.capacity then raise exception 'slot_full'; end if;

    v_ready := (p_scheduled_date + v_slot.start_time) at time zone 'Africa/Cairo';
    v_dispatch := v_ready - make_interval(mins => v_buffer);
  else
    v_ready := now() + make_interval(mins => v_prep);
    v_dispatch := greatest(now(), v_ready - make_interval(mins => v_buffer));
  end if;

  v_status := case
    when (p_payment_method in ('online','instapay') and v_net_total > 0) or v_cod_deposit is not null
      then 'awaiting_payment'
    -- 'Scheduled' is for pre-booked SLOT orders only. An ASAP order also has a
    -- future dispatch_at (now + prep - buffer) -- that is the DRIVER's clock,
    -- not the customer's booking. Gating on dispatch_at alone put every normal
    -- order at a restaurant with prep > buffer into 'Scheduled' at birth: the
    -- vendor nudges never rang (they require 'pending'), the driver pool hid
    -- it, and Track told the customer it was booked for later.
    when p_slot_id is not null and v_dispatch is not null and v_dispatch > now()
      then 'Scheduled'
    else 'pending'
  end;

  insert into orders (restaurant_id, customer_name, customer_phone, zone, unit_number,
                      address_notes, customer_note, subtotal, delivery_fee, service_fee, wallet_used, total,
                      ready_at, dispatch_at, slot_id, scheduled_date, compound_id,
                      status, payment_method, online_payment_status, sla_minutes, customer_id, cod_deposit_amount)
  values (p_restaurant_id, trim(p_customer_name), trim(p_customer_phone), p_zone,
          trim(p_unit_number), coalesce(p_address_notes,''), nullif(trim(coalesce(p_customer_note,'')),''),
          v_subtotal, v_fee, v_service_fee, v_wallet_used,
          v_net_total, v_ready, v_dispatch, p_slot_id, p_scheduled_date, p_compound_id,
          v_status, p_payment_method,
          case when p_payment_method in ('online','instapay') and v_net_total > 0 then 'pending'
               when v_cod_deposit is not null then 'pending' else null end,
          v_sla, v_customer_id, v_cod_deposit)
  returning id, public_token into v_order_id, v_token;

  if v_wallet_used > 0 then
    update customer_wallets set balance = balance - v_wallet_used where id = v_wallet_id;
    insert into wallet_transactions (wallet_id, amount, reason, order_id)
      values (v_wallet_id, -v_wallet_used, 'استخدام الرصيد في طلب #' || v_order_id, v_order_id);
  end if;

  insert into order_items (order_id, menu_item_id, name, qty, unit_price, total, requires_prescription, size_name, combo_name, addon_names, original_unit_price)
  select v_order_id, (l->>'menu_item_id')::int, l->>'name', (l->>'qty')::int, (l->>'unit_price')::numeric,
         (l->>'qty')::int * (l->>'unit_price')::numeric, (l->>'requires_prescription')::boolean,
         l->>'size_name', l->>'combo_name',
         case when jsonb_array_length(coalesce(l->'addon_names','[]'::jsonb)) = 0 then null
              else array(select jsonb_array_elements_text(l->'addon_names')) end,
         (l->>'original_unit_price')::numeric
  from jsonb_array_elements(v_lines) as l;

  return json_build_object('id', v_order_id, 'token', v_token,
                           'ready_at', v_ready, 'dispatch_at', v_dispatch, 'wallet_used', v_wallet_used,
                           'cod_deposit_amount', v_cod_deposit);
end; $function$

CREATE OR REPLACE FUNCTION private.admin_add_menu_category(p_restaurant_id integer, p_name text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_name text := btrim(p_name); v_id int;
begin
  if not (is_admin() or is_catalog_manager()) then raise exception 'not_authorized'; end if;
  if coalesce(v_name,'') = '' then raise exception 'name_required'; end if;
  if exists (select 1 from menu_categories
              where restaurant_id = p_restaurant_id and lower(btrim(name)) = lower(v_name)) then
    raise exception 'category_exists';
  end if;
  insert into menu_categories (restaurant_id, name, display_order)
  values (p_restaurant_id, v_name,
          coalesce((select max(display_order)+1 from menu_categories where restaurant_id = p_restaurant_id), 1))
  returning id into v_id;
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION private.admin_delete_menu_category(p_restaurant_id integer, p_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n int;
begin
  if not (is_admin() or is_catalog_manager()) then raise exception 'not_authorized'; end if;
  select count(*) into v_n from menu_items
   where restaurant_id = p_restaurant_id and lower(btrim(category)) = lower(btrim(p_name));
  if v_n > 0 then raise exception 'category_not_empty:%', v_n; end if;
  delete from menu_categories
   where restaurant_id = p_restaurant_id and lower(btrim(name)) = lower(btrim(p_name));
end $function$

CREATE OR REPLACE FUNCTION private.admin_delete_menu_item(p_item_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not is_admin() then raise exception 'admin_only'; end if;
  if exists (select 1 from order_items where menu_item_id = p_item_id) then
    raise exception 'item_has_order_history';
  end if;
  delete from menu_items where id = p_item_id;
end; $function$

CREATE OR REPLACE FUNCTION private.admin_flag_driver_dispute(p_complaint_id integer, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_order_id int; v_driver_id int;
begin
  if not is_admin() then raise exception 'admin_only'; end if;

  select order_id, driver_id into v_order_id, v_driver_id from complaints where id = p_complaint_id;
  if v_order_id is null then raise exception 'complaint_not_found'; end if;
  if v_driver_id is null then raise exception 'no_driver_on_this_complaint'; end if;

  update driver_earnings set disputed = true, dispute_note = nullif(trim(p_note), '')
  where order_id = v_order_id and driver_id = v_driver_id;
end; $function$

CREATE OR REPLACE FUNCTION private.admin_push_health()
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not is_supervisor() then raise exception 'admin_only'; end if;
  return json_build_object(
    'tokens', (select coalesce(json_agg(json_build_object(
        'role', p.role, 'name', p.name, 'platform', pt.platform,
        'prefix', left(pt.token, 12) || '...', 'updated_at', pt.updated_at) order by p.role), '[]'::json)
      from push_tokens pt left join profiles p on p.id = pt.profile_id),
    'recent_failures', (select coalesce(json_agg(json_build_object(
        'prefix', token_prefix, 'status', status, 'err', err_code,
        'title', title, 'at', created_at) order by created_at desc), '[]'::json)
      from (select * from push_send_log where not ok order by created_at desc limit 20) f),
    'sent_24h', (select count(*) from push_send_log where created_at > now() - interval '24 hours'),
    'failed_24h', (select count(*) from push_send_log where not ok and created_at > now() - interval '24 hours')
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.admin_rename_menu_category(p_restaurant_id integer, p_old text, p_new text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_new text := btrim(p_new);
begin
  if not (is_admin() or is_catalog_manager()) then raise exception 'not_authorized'; end if;
  if coalesce(v_new,'') = '' then raise exception 'name_required'; end if;
  if exists (select 1 from menu_categories
              where restaurant_id = p_restaurant_id
                and lower(btrim(name)) = lower(v_new)
                and lower(btrim(name)) <> lower(btrim(p_old))) then
    raise exception 'category_exists';
  end if;

  update menu_categories set name = v_new
   where restaurant_id = p_restaurant_id and lower(btrim(name)) = lower(btrim(p_old));
  update menu_items set category = v_new
   where restaurant_id = p_restaurant_id and lower(btrim(category)) = lower(btrim(p_old));
end $function$

CREATE OR REPLACE FUNCTION private.admin_set_compound_fee(p_compound_id integer, p_fee numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not is_admin() then raise exception 'admin_only'; end if;
  if p_fee is null or p_fee < 0 then raise exception 'invalid_fee'; end if;
  if p_fee > 2000 then raise exception 'fee_too_large'; end if;
  update compounds set delivery_fee = round(p_fee) where id = p_compound_id;
  if not found then raise exception 'compound_not_found'; end if;
end $function$

CREATE OR REPLACE FUNCTION private.admin_set_restaurant_rank(p_restaurant_id integer, p_display_order integer, p_featured boolean DEFAULT NULL::boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not is_admin() then raise exception 'admin_only'; end if;
  if p_display_order is not null and p_display_order < 1 then
    raise exception 'rank_must_be_positive';
  end if;
  update restaurants
     set display_order = p_display_order,
         featured = coalesce(p_featured, featured)
   where id = p_restaurant_id;
  if not found then raise exception 'restaurant_not_found'; end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.admin_set_vendor_hours(p_restaurant_id integer, p_days jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d jsonb; v_day int; v_o time; v_c time; v_closed boolean;
begin
  if not is_admin() then raise exception 'admin_only'; end if;
  if not exists (select 1 from restaurants where id = p_restaurant_id and not archived) then
    raise exception 'restaurant_not_found';
  end if;

  -- An empty array means "no hours", i.e. always open. A real setting, and the
  -- state every vendor is in today.
  delete from vendor_hours where restaurant_id = p_restaurant_id;
  if p_days is null or jsonb_array_length(p_days) = 0 then return; end if;

  for d in select * from jsonb_array_elements(p_days) loop
    v_day    := (d->>'day')::int;
    v_closed := coalesce((d->>'closed')::boolean, false);
    v_o      := nullif(d->>'opens','')::time;
    v_c      := nullif(d->>'closes','')::time;

    if v_day is null or v_day < 0 or v_day > 6 then
      raise exception 'invalid_day';
    end if;
    -- Half a window is not a window; the open/closed test would read it as a
    -- day with no hours and quietly close the vendor.
    if not v_closed and ((v_o is null) <> (v_c is null)) then
      raise exception 'hours_incomplete';
    end if;
    -- A day with neither times nor the closed flag carries no information.
    if not v_closed and v_o is null then
      continue;
    end if;

    insert into vendor_hours (restaurant_id, day_of_week, opens_at, closes_at, closed)
    values (p_restaurant_id, v_day,
            case when v_closed then null else v_o end,
            case when v_closed then null else v_c end,
            v_closed);
  end loop;
end $function$

CREATE OR REPLACE FUNCTION private.admin_upsert_compound(p_id integer, p_name text, p_region_id integer, p_delivery_fee numeric, p_distance_km numeric DEFAULT NULL::numeric, p_direction text DEFAULT NULL::text, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric, p_active boolean DEFAULT true)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id int;
begin
  if not is_admin() then raise exception 'admin_only'; end if;
  if coalesce(trim(p_name), '') = '' then raise exception 'name_required'; end if;
  -- delivery_fee is NOT NULL on the table and place_order refuses an order to a
  -- compound without one, so a compound created without a fee would be a place
  -- customers can pick and can never order to.
  if p_delivery_fee is null or p_delivery_fee <= 0 then raise exception 'delivery_fee_required'; end if;
  if not exists (select 1 from regions where id = p_region_id) then raise exception 'region_not_found'; end if;
  if p_direction is not null and p_direction not in ('north','south') then raise exception 'invalid_direction'; end if;

  if p_id is null then
    insert into compounds (name, region_id, delivery_fee, distance_km, direction, latitude, longitude, active)
    values (trim(p_name), p_region_id, p_delivery_fee, p_distance_km, p_direction, p_latitude, p_longitude, coalesce(p_active, true))
    returning id into v_id;
  else
    update compounds
       set name = trim(p_name), region_id = p_region_id, delivery_fee = p_delivery_fee,
           distance_km = p_distance_km, direction = p_direction,
           latitude = p_latitude, longitude = p_longitude, active = coalesce(p_active, true)
     where id = p_id
     returning id into v_id;
    if v_id is null then raise exception 'compound_not_found'; end if;
  end if;

  return json_build_object('id', v_id, 'created', p_id is null);
end $function$

CREATE OR REPLACE FUNCTION private.apply_library_addon(p_library_id integer, p_item_ids integer[], p_group_name text DEFAULT 'إضافات'::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_lib vendor_addon_library%rowtype;
  v_item_id int;
  v_group_id int;
  v_applied int := 0;
  v_item_restaurant int;
begin
  if not (is_admin() or is_catalog_manager()) then raise exception 'not_authorised'; end if;

  select * into v_lib from vendor_addon_library where id = p_library_id;
  if not found then raise exception 'library_item_not_found'; end if;

  if p_item_ids is null or array_length(p_item_ids, 1) is null then return 0; end if;
  if coalesce(trim(p_group_name), '') = '' then raise exception 'group_name_required'; end if;

  foreach v_item_id in array p_item_ids loop
    select restaurant_id into v_item_restaurant from menu_items where id = v_item_id;
    -- Silently skipping a foreign item would let a typo in one array quietly
    -- half-apply. An item from another vendor is a caller bug, so say so.
    if v_item_restaurant is null then raise exception 'menu_item_not_found: %', v_item_id; end if;
    if v_item_restaurant <> v_lib.restaurant_id then raise exception 'item_belongs_to_another_vendor: %', v_item_id; end if;

    select id into v_group_id from menu_item_addon_groups
      where menu_item_id = v_item_id and name = trim(p_group_name) limit 1;
    if v_group_id is null then
      insert into menu_item_addon_groups (menu_item_id, name, min_select, max_select, display_order)
      values (v_item_id, trim(p_group_name), 0, null,
              coalesce((select max(display_order) + 1 from menu_item_addon_groups where menu_item_id = v_item_id), 0))
      returning id into v_group_id;
    end if;

    if not exists (select 1 from menu_item_addons where group_id = v_group_id and name = v_lib.name) then
      insert into menu_item_addons (group_id, name, price, image_url, display_order)
      values (v_group_id, v_lib.name, v_lib.price, v_lib.image_url,
              coalesce((select max(display_order) + 1 from menu_item_addons where group_id = v_group_id), 0));
      v_applied := v_applied + 1;
    end if;
  end loop;

  return v_applied;
end; $function$

CREATE OR REPLACE FUNCTION private.claim_order(p_order_id integer)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_driver int; v_attempt int; v_id int; v_vendor_type text; v_vehicle text;
  v_active_count int; v_active boolean; v_drv_test boolean; v_ord_test boolean;
  v_subtotal numeric; v_pricing_status text; v_threshold numeric; v_needs_van boolean;
  v_dispatch_at timestamptz;
begin
  v_driver := my_driver_id();
  if v_driver is null then raise exception 'not_a_driver'; end if;

  perform pg_advisory_xact_lock(v_driver);

  select active, is_test into v_active, v_drv_test from drivers where id = v_driver;
  if not v_active then raise exception 'driver_suspended'; end if;

  select r.vendor_type, o.subtotal, o.pricing_status, coalesce(o.dispatch_at, o.created_at), o.is_test
    into v_vendor_type, v_subtotal, v_pricing_status, v_dispatch_at, v_ord_test
  from orders o join restaurants r on r.id = o.restaurant_id where o.id = p_order_id;

  -- A real driver must never be able to reach a test order, and the test driver
  -- must never reach a real one. Not filtered -- refused.
  if v_ord_test is distinct from v_drv_test then raise exception 'not_your_pool'; end if;

  if v_dispatch_at > now() then raise exception 'not_ready_yet'; end if;

  if not is_predispatch_status((select status from orders where id = p_order_id)) then
    raise exception 'already_taken';
  end if;

  if not order_is_dispatchable(p_order_id) then
    raise exception 'kitchen_not_accepted_yet';
  end if;

  select vehicle_type into v_vehicle from drivers where id = v_driver;

  select coalesce((select value::numeric from settings where key = 'van_required_subtotal_egp'), 300)
    into v_threshold;

  if v_pricing_status = 'pending_quote' then raise exception 'order_not_priced'; end if;

  v_needs_van := v_vendor_type = 'supermarket'
    and (v_pricing_status = 'pending_quote' or coalesce(v_subtotal, 0) >= v_threshold);

  if v_needs_van and v_vehicle <> 'van' then
    raise exception 'wrong_vehicle_type';
  end if;

  if not driver_can_take_order(v_driver, p_order_id) then
    raise exception 'dispatch_rule_blocked';
  end if;

  perform 1 from orders where id = p_order_id for update;

  if exists (select 1 from delivery_assignments
             where order_id = p_order_id
               and status in ('Offered','Accepted','Picked_Up','Out_for_Delivery','Delivered')) then
    raise exception 'already_taken';
  end if;

  select coalesce(max(attempt_number),0) + 1 into v_attempt
    from delivery_assignments where order_id = p_order_id;

  insert into delivery_assignments (order_id, driver_id, attempt_number, status,
                                    offered_at, responded_at)
  values (p_order_id, v_driver, v_attempt, 'Accepted', now(), now())
  returning id into v_id;

  select count(*) into v_active_count from delivery_assignments
    where driver_id = v_driver and status in ('Accepted','Picked_Up','Out_for_Delivery');

  update orders set status = 'Accepted' where id = p_order_id;
  update drivers set status = 'On_Delivery', available = (v_active_count < 3) where id = v_driver;

  return json_build_object('assignment_id', v_id);
end; $function$

