CREATE OR REPLACE FUNCTION private.driver_claim_device(p_device_id text, p_label text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_did int; v_current text; v_outcome text;
begin
  v_did := my_driver_id();
  if v_did is null then raise exception 'not_a_driver'; end if;
  if coalesce(trim(p_device_id), '') = '' then raise exception 'invalid_device'; end if;

  -- Serialise per driver: two phones opening the app in the same second must
  -- not both read a null device_id and both claim it.
  perform pg_advisory_xact_lock(hashtext('driver_device:' || v_did));

  select device_id into v_current from drivers where id = v_did;

  if v_current is null then
    update drivers
       set device_id = p_device_id,
           device_label = nullif(trim(coalesce(p_label, '')), ''),
           device_bound_at = now()
     where id = v_did;
    v_outcome := 'bound';

  elsif v_current = p_device_id then
    v_outcome := 'matched';

  else
    insert into driver_device_log (driver_id, device_id, device_label, outcome)
    values (v_did, p_device_id, nullif(trim(coalesce(p_label,'')),''), 'refused');
    raise exception 'device_locked';
  end if;

  -- 'matched' is the every-10-seconds case, so do not write a log row for it.
  if v_outcome = 'bound' then
    insert into driver_device_log (driver_id, device_id, device_label, outcome)
    values (v_did, p_device_id, nullif(trim(coalesce(p_label,'')),''), 'bound');
  end if;

  return json_build_object('outcome', v_outcome);
end $function$

