CREATE OR REPLACE FUNCTION private.driver_mark_picked_up(p_assignment_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_driver int; v_status text; v_order_id int; v_arrived timestamptz; v_kitchen_status text;
begin
  v_driver := my_driver_id();
  if v_driver is null then raise exception 'not_a_driver'; end if;

  select da.status, da.order_id, da.arrived_at_restaurant_at, o.kitchen_status
    into v_status, v_order_id, v_arrived, v_kitchen_status
