  if v_arrived is null then raise exception 'must_arrive_first'; end if;
  if v_kitchen_status <> 'ready' then raise exception 'order_not_ready'; end if;

  update delivery_assignments set status = 'Picked_Up', picked_up_at = now() where id = p_assignment_id;
  update orders set status = 'Picked_Up' where id = v_order_id;
