CREATE OR REPLACE FUNCTION private.driver_reject_assignment(p_assignment_id integer, p_reason text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_driver int; v_status text; v_order_id int;
begin
  v_driver := my_driver_id();
  if v_driver is null then raise exception 'not_a_driver'; end if;

  select status, order_id into v_status, v_order_id
  from delivery_assignments where id = p_assignment_id and driver_id = v_driver;
  if v_order_id is null then raise exception 'not_your_assignment'; end if;
  if v_status <> 'Offered' then raise exception 'wrong_stage'; end if;

  update delivery_assignments set status = 'Rejected', responded_at = now(),
    rejection_reason = coalesce(nullif(trim(p_reason), ''), 'driver_declined')
  where id = p_assignment_id;

  -- Was an unconditional `set status = 'pending'`, which also silently reset an
  -- order that had progressed past the offer.
  update orders set status = 'Driver_Searching'
   where id = v_order_id and is_predispatch_status(status);
end $function$

CREATE OR REPLACE FUNCTION private.driver_report_no_answer(p_assignment_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_driver int; v_order_id int; v_out_at timestamptz; v_called_at timestamptz;
begin
  v_driver := my_driver_id();
  if v_driver is null then raise exception 'not_a_driver'; end if;

  select order_id, out_for_delivery_at, called_customer_at into v_order_id, v_out_at, v_called_at
    from delivery_assignments where id = p_assignment_id and driver_id = v_driver;
  if v_order_id is null then raise exception 'not_your_assignment'; end if;
  if v_called_at is null then raise exception 'must_call_customer_first'; end if;
  if v_out_at is null or now() - v_out_at < interval '5 minutes' then raise exception 'too_early'; end if;

  update delivery_assignments set no_answer_reported_at = now() where id = p_assignment_id;
  perform notify_admin('العميل ما ردش ☎️', 'طلب #' || v_order_id || ' — المندوب اتصل والعميل ما ردش، محتاج قرار',
    jsonb_build_object('order_id', v_order_id, 'type', 'no_answer'));
end; $function$

CREATE OR REPLACE FUNCTION private.driver_report_problem(p_assignment_id integer, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_driver int; v_status text; v_order int;
begin
  v_driver := my_driver_id();
  if v_driver is null then raise exception 'not_a_driver'; end if;
  if coalesce(trim(p_reason), '') = '' then raise exception 'reason_required'; end if;

  select status, order_id into v_status, v_order from delivery_assignments
   where id = p_assignment_id and driver_id = v_driver;
  if v_status is null then raise exception 'not_your_assignment'; end if;
  if v_status not in ('Accepted','Picked_Up','Out_for_Delivery') then
    raise exception 'wrong_stage';
  end if;

  update delivery_assignments
     set no_answer_reported_at   = coalesce(no_answer_reported_at, now()),
         no_answer_admin_action  = null,
         delivery_problem_reason = left(trim(p_reason), 300)
   where id = p_assignment_id;

  perform notify_admin('مشكلة في التوصيل 🛵',
    'طلب #' || v_order || ' — ' || left(trim(p_reason), 120),
    jsonb_build_object('order_id', v_order, 'type', 'driver_problem'));
end $function$

CREATE OR REPLACE FUNCTION private.driver_set_available(p_available boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_did int; v_active boolean; v_live int;
begin
  v_did := my_driver_id();
  if v_did is null then raise exception 'not_a_driver'; end if;
  if p_available is null then raise exception 'invalid_state'; end if;

  select active into v_active from drivers where id = v_did;
  if p_available and not coalesce(v_active, false) then raise exception 'driver_suspended'; end if;

  -- Going unavailable with live deliveries would strand them. Say so rather
  -- than silently doing half of it.
  if not p_available then
    select count(*) into v_live from delivery_assignments
     where driver_id = v_did and status in ('Accepted','Picked_Up','Out_for_Delivery');
    if v_live > 0 then raise exception 'finish_your_orders_first'; end if;
  end if;

  update drivers
     set available = p_available,
         status = case
           when not p_available then 'Offline'
           when status = 'Offline' then 'Available'
           else status
         end
   where id = v_did;
end $function$

CREATE OR REPLACE FUNCTION private.mark_delivered(p_assignment_id integer, p_order_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_driver int; v_status text; v_total numeric; v_fee numeric;
  v_driver_earning numeric; v_admin_amount numeric;
  v_payment_method text; v_cod_deposit numeric; v_cash_due numeric;
  v_cash_confirmed timestamptz; v_remaining int; v_is_test boolean;
begin
  select driver_id, status, cash_confirmed_at into v_driver, v_status, v_cash_confirmed
    from delivery_assignments where id = p_assignment_id;
  if v_driver is null or v_driver <> my_driver_id() then raise exception 'not_your_assignment'; end if;
  if v_status <> 'Out_for_Delivery' then raise exception 'wrong_stage'; end if;

  select total, delivery_fee, payment_method, cod_deposit_amount, is_test
    into v_total, v_fee, v_payment_method, v_cod_deposit, v_is_test
    from orders where id = p_order_id;

  v_cash_due := case
    when v_payment_method = 'instapay' then 0
    when v_cod_deposit is not null then v_total - v_cod_deposit
    else v_total
  end;

  -- Still exercised on a test order, so the cash-confirm step itself gets
  -- tested; it just does not become real money below.
  if v_cash_due > 0 and v_cash_confirmed is null then
    raise exception 'must_confirm_cash_first';
  end if;

  update delivery_assignments set status = 'Delivered', delivered_at = now() where id = p_assignment_id;
  update orders set status = 'Delivered' where id = p_order_id;

  select count(*) into v_remaining from delivery_assignments
    where driver_id = v_driver and status in ('Accepted','Picked_Up','Out_for_Delivery');

  if v_is_test then
    -- Clear the driver's queue so the flow completes, but touch no money and
    -- no lifetime counter.
    update drivers set
      status    = case when v_remaining = 0 then 'Available' else status end,
      available = (v_remaining < 3)
    where id = v_driver;
    return;
  end if;

  v_fee := coalesce(v_fee, 65);

  select coalesce((select value::numeric from settings where key = 'driver_flat_earning_egp'), 10)
    into v_driver_earning;
  v_driver_earning := least(greatest(v_driver_earning, 0), v_fee);
  v_admin_amount := v_fee - v_driver_earning;

  insert into driver_earnings (driver_id, order_id, assignment_id, delivery_fee, driver_earning, admin_amount)
  values (v_driver, p_order_id, p_assignment_id, v_fee, v_driver_earning, v_admin_amount)
  on conflict (assignment_id) do nothing;

  update drivers set
    status           = case when v_remaining = 0 then 'Available' else status end,
    available        = (v_remaining < 3),
    total_deliveries = coalesce(total_deliveries, 0) + 1,
    cash_held        = coalesce(cash_held, 0) + greatest(coalesce(v_cash_due, 0), 0)
  where id = v_driver;
end; $function$

CREATE OR REPLACE FUNCTION private.my_driver_stats()
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_driver integer;
  v_total integer;
  v_streak integer := 0;
  v_check date := current_date;
  v_has boolean;
  v_today date;
  v_today_orders integer;
  v_today_earnings numeric;
  v_today_tips numeric;
  v_today_reported_tips numeric;
  v_unpaid numeric;
  v_cash numeric;
  v_t1_o integer;
  v_t1_a numeric;
  v_t2_o integer;
  v_t2_a numeric;
  v_t3_o integer;
  v_t3_a numeric;
  v_tier integer := 0;
  v_earned numeric := 0;
  v_next_o integer;
  v_next_a numeric;
begin
  v_driver := public.my_driver_id();
  if v_driver is null then raise exception 'not_a_driver'; end if;

  select coalesce(d.total_deliveries, 0), coalesce(d.cash_held, 0)
    into v_total, v_cash
    from public.drivers d
   where d.id = v_driver;

  loop
    select exists(
      select 1
        from public.delivery_assignments da
       where da.driver_id = v_driver
         and da.status = 'Delivered'
         and da.delivered_at::date = v_check
    ) into v_has;
    exit when not v_has;
    v_streak := v_streak + 1;
    v_check := v_check - 1;
    exit when v_streak > 365;
  end loop;

  v_today := (now() at time zone 'Africa/Cairo')::date;

  select count(*), coalesce(sum(de.driver_earning), 0)
    into v_today_orders, v_today_earnings
    from public.driver_earnings de
   where de.driver_id = v_driver
     and (de.created_at at time zone 'Africa/Cairo')::date = v_today;

  select
    coalesce(sum(dt.amount) filter (where dt.status = 'confirmed'), 0),
    coalesce(sum(dt.amount) filter (where dt.status = 'reported'), 0)
    into v_today_tips, v_today_reported_tips
    from public.driver_tips dt
   where dt.driver_id = v_driver
     and (dt.created_at at time zone 'Africa/Cairo')::date = v_today;

  select coalesce(sum(de.driver_earning), 0)
    into v_unpaid
    from public.driver_earnings de
   where de.driver_id = v_driver
     and not coalesce(de.paid, false);

  select coalesce((select value::integer from public.settings where key = 'driver_bonus_tier1_orders'), 24) into v_t1_o;
  select coalesce((select value::numeric from public.settings where key = 'driver_bonus_tier1_amount'), 100) into v_t1_a;
  select coalesce((select value::integer from public.settings where key = 'driver_bonus_tier2_orders'), 30) into v_t2_o;
  select coalesce((select value::numeric from public.settings where key = 'driver_bonus_tier2_amount'), 150) into v_t2_a;
  select coalesce((select value::integer from public.settings where key = 'driver_bonus_tier3_orders'), 38) into v_t3_o;
  select coalesce((select value::numeric from public.settings where key = 'driver_bonus_tier3_amount'), 200) into v_t3_a;

  if v_today_orders >= v_t3_o then
    v_tier := 3; v_earned := v_t3_a; v_next_o := null; v_next_a := null;
  elsif v_today_orders >= v_t2_o then
    v_tier := 2; v_earned := v_t2_a; v_next_o := v_t3_o; v_next_a := v_t3_a;
  elsif v_today_orders >= v_t1_o then
    v_tier := 1; v_earned := v_t1_a; v_next_o := v_t2_o; v_next_a := v_t2_a;
  else
    v_tier := 0; v_earned := 0; v_next_o := v_t1_o; v_next_a := v_t1_a;
  end if;

  return json_build_object(
    'total_deliveries', v_total,
    'streak_days', v_streak,
    'today_orders', v_today_orders,
    'today_earnings', v_today_earnings,
    -- Compatibility field for installed clients: verified tips only.
    'today_tips', v_today_tips,
    -- New clients display this as an unverified customer report.
    'today_reported_tips', v_today_reported_tips,
    'unpaid_earnings', v_unpaid,
    'cash_held', v_cash,
    'bonus', json_build_object(
      'tiers', json_build_array(
        json_build_object('orders', v_t1_o, 'amount', v_t1_a),
        json_build_object('orders', v_t2_o, 'amount', v_t2_a),
        json_build_object('orders', v_t3_o, 'amount', v_t3_a)
      ),
      'current_tier', v_tier,
      'earned_today', v_earned,
      'next_orders', v_next_o,
      'next_amount', v_next_a,
      'orders_to_next', case
        when v_next_o is null then null
        else greatest(0, v_next_o - v_today_orders)
      end
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.restaurant_reliability(p_restaurant_id integer)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_restaurant_id is null then
    raise exception 'restaurant_required';
  end if;

  if not public.is_admin()
     and p_restaurant_id is distinct from public.my_restaurant_id() then
    raise exception 'not_authorized';
  end if;

  return json_build_object(
    'avg_accept_minutes', (
      select round(
        avg(extract(epoch from (o.vendor_accepted_at - o.created_at)) / 60)::numeric,
        1
      )
      from public.orders o
      where o.restaurant_id = p_restaurant_id
        and o.vendor_accepted_at is not null
        and o.created_at > now() - interval '30 days'
    ),
    'slow_accepts', (
      select count(*)
      from public.orders o
      where o.restaurant_id = p_restaurant_id
        and o.vendor_accepted_at is not null
        and o.created_at > now() - interval '30 days'
        and extract(epoch from (o.vendor_accepted_at - o.created_at)) / 60 > 5
    ),
    'total_orders', (
      select count(*)
      from public.orders o
      where o.restaurant_id = p_restaurant_id
        and o.created_at > now() - interval '30 days'
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.save_my_push_token(p_push_token text, p_platform text DEFAULT 'web'::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_was_dead boolean;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if p_platform not in ('web','android','ios') then raise exception 'bad_platform'; end if;
  if coalesce(btrim(p_push_token),'') = '' then raise exception 'empty_token'; end if;

  select true into v_was_dead from dead_push_tokens where token = p_push_token;
  if coalesce(v_was_dead, false) then
    return json_build_object('stored', false, 'stale', true);
  end if;

  insert into push_tokens (profile_id, token, platform, updated_at)
  values (auth.uid(), p_push_token, p_platform, now())
  on conflict (token) do update
    set profile_id = excluded.profile_id,
        platform   = excluded.platform,
        updated_at = now();

  delete from push_tokens
   where profile_id = auth.uid()
     and updated_at < now() - interval '60 days';

  delete from push_tokens
   where profile_id = auth.uid()
     and id not in (
       select id from push_tokens
        where profile_id = auth.uid()
        order by updated_at desc, id desc
        limit 4);

  return json_build_object('stored', true, 'stale', false);
end;
$function$

CREATE OR REPLACE FUNCTION private.update_my_location(p_lat numeric, p_lng numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_driver int;
begin
  v_driver := my_driver_id();
  if v_driver is null then raise exception 'not_a_driver'; end if;

  -- Silently ignore rather than raise. A position arriving a few seconds after
  -- the last delivery completed is a normal race with the 20s reporting tick,
  -- not an error worth showing a driver who has just finished his shift.
  if not exists (
    select 1 from delivery_assignments
     where driver_id = v_driver
       and status in ('Picked_Up', 'Out_for_Delivery')
  ) then
    return;
  end if;

  update drivers set current_lat = p_lat, current_lng = p_lng, location_updated_at = now()
  where id = v_driver;
end; $function$

CREATE OR REPLACE FUNCTION private.request_early_settlement()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_driver int;
begin
  v_driver := my_driver_id();
  if v_driver is null then raise exception 'not_a_driver'; end if;
  insert into settlement_requests (driver_id) values (v_driver);
end; $function$

CREATE OR REPLACE FUNCTION private.request_pickup(p_restaurant_id integer, p_customer_name text, p_customer_phone text, p_zone text, p_unit_number text, p_address_notes text, p_delivery_fee numeric, p_payment_mode text, p_collect_amount numeric, p_request_notes text, p_compound_id integer DEFAULT NULL::integer, p_session_token uuid DEFAULT NULL::uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order_id int; v_token uuid; v_prep int; v_buffer int; v_ready timestamptz; v_dispatch timestamptz;
  v_total numeric; v_fee numeric; v_km numeric; v_exists boolean; v_sla int; v_customer_id int;
  v_pct numeric; v_service numeric; v_goods numeric;
begin
  if coalesce(trim(p_customer_name),'') = '' or coalesce(trim(p_customer_phone),'') = ''
     or coalesce(trim(p_zone),'') = '' or coalesce(trim(p_unit_number),'') = '' then
    raise exception 'missing_customer_details';
  end if;
  if p_payment_mode not in ('prepaid','driver_pays') then raise exception 'invalid_payment_mode'; end if;
  if p_payment_mode = 'driver_pays' and coalesce(p_collect_amount, 0) <= 0 then
    raise exception 'collect_amount_required';
  end if;

  if p_session_token is not null then
    select cs.customer_id into v_customer_id
      from customer_sessions cs where cs.token = p_session_token and cs.expires_at > now();
  end if;

  select true, coalesce(prep_minutes, 10) into v_exists, v_prep
    from restaurants where id = p_restaurant_id;
  if not v_exists then raise exception 'restaurant_not_found'; end if;

  if p_compound_id is null then raise exception 'compound_id_required'; end if;
  select distance_km, delivery_fee into v_km, v_fee from compounds where id = p_compound_id;
  if v_km is null then raise exception 'compound_missing_distance'; end if;
  if v_fee is null then raise exception 'compound_missing_fee'; end if;
  v_sla := sla_minutes_for(p_restaurant_id, p_compound_id);

  select coalesce((select value::int from settings where key = 'travel_buffer_minutes'), 10) into v_buffer;
  v_ready := now() + make_interval(mins => v_prep);
  v_dispatch := greatest(now(), v_ready - make_interval(mins => v_buffer));

  -- Only what the driver actually collects carries the fee. On a prepaid order
  -- the vendor already took the customer's money and Salka is paid the delivery
  -- fee alone, so charging 8% of goods we never handle would invent a number
  -- nobody owes. Same source, base and rounding as place_order otherwise.
  v_goods := case when p_payment_mode = 'driver_pays' then coalesce(p_collect_amount, 0) else 0 end;
  select coalesce((select value::numeric from settings where key = 'service_fee_percent'), 0) into v_pct;
  v_service := round(v_goods * v_pct / 100.0);
  v_total := v_fee + v_goods + v_service;

  insert into orders (restaurant_id, customer_name, customer_phone, zone, unit_number,
                      address_notes, subtotal, delivery_fee, service_fee, total,
                      order_type, request_notes, pricing_status, kitchen_status,
                      payment_mode, collect_amount, ready_at, dispatch_at, compound_id, sla_minutes, customer_id)
  values (p_restaurant_id, trim(p_customer_name), trim(p_customer_phone), p_zone,
          trim(p_unit_number), coalesce(p_address_notes,''),
          coalesce(p_collect_amount, 0), v_fee, v_service, v_total,
          'pickup_request', coalesce(p_request_notes,''), 'n/a', 'ready',
          p_payment_mode, p_collect_amount, v_ready, v_dispatch, p_compound_id, v_sla, v_customer_id)
  returning id, public_token into v_order_id, v_token;

  return json_build_object('id', v_order_id, 'token', v_token,
                           'total', v_total, 'delivery_fee', v_fee, 'service_fee', v_service,
                           'collect_amount', coalesce(p_collect_amount, 0));
end; $function$

CREATE OR REPLACE FUNCTION private.request_swap(p_shift_id integer, p_reason text DEFAULT ''::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_driver int; v_id int;
begin
  v_driver := my_driver_id();
  if v_driver is null then raise exception 'not_a_driver'; end if;

  if not exists (select 1 from shifts where id = p_shift_id and driver_id = v_driver
                 and status = 'scheduled') then
    raise exception 'not_your_shift';
  end if;

  if exists (select 1 from shift_swap_requests
             where shift_id = p_shift_id and status = 'open') then
    raise exception 'already_requested';
  end if;

  insert into shift_swap_requests (shift_id, requested_by, reason)
  values (p_shift_id, v_driver, trim(p_reason))
  returning id into v_id;

  return json_build_object('request_id', v_id);
end; $function$

CREATE OR REPLACE FUNCTION private.save_customer_push_token(p_token uuid, p_push_token text, p_platform text DEFAULT 'web'::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_push_token text;
  v_order_id integer;
  v_existing_token text;
  v_customer_auth_user_id uuid;
  v_is_owner boolean;
begin
  if p_platform not in ('web','android','ios') then raise exception 'bad_platform'; end if;

  v_push_token := nullif(btrim(coalesce(p_push_token, '')), '');
  if v_push_token is null then raise exception 'empty_token'; end if;
  if length(v_push_token) > 4096 then raise exception 'token_too_long'; end if;

  if exists (select 1 from public.dead_push_tokens d where d.token = v_push_token) then
    return json_build_object('stored', false, 'stale', true, 'conflict', false);
  end if;

  -- Lock just the order row so simultaneous registrations cannot both observe
  -- an empty destination and silently replace one another.
  select o.id, o.push_token, c.auth_user_id
    into v_order_id, v_existing_token, v_customer_auth_user_id
    from public.orders o
    left join public.customers c on c.id = o.customer_id
   where o.public_token = p_token
   for update of o;

  if v_order_id is null then
    return json_build_object('stored', false, 'stale', false, 'conflict', false);
  end if;

  v_is_owner := auth.uid() is not null
                and auth.uid() = v_customer_auth_user_id;

  if v_existing_token is not null
     and v_existing_token is distinct from v_push_token
     and not v_is_owner then
    return json_build_object('stored', false, 'stale', false, 'conflict', true);
  end if;

  update public.orders
     set push_token = v_push_token,
         push_platform = p_platform
   where id = v_order_id;

  return json_build_object('stored', true, 'stale', false, 'conflict', false);
end;
$function$

CREATE OR REPLACE FUNCTION private.set_default_address(p_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_customer_id int;
begin
  v_customer_id := my_customer_id();
  if not exists (select 1 from customer_addresses where id = p_id and customer_id = v_customer_id) then
    raise exception 'not_your_address';
  end if;
  update customer_addresses set is_default = (id = p_id) where customer_id = v_customer_id;
end; $function$

CREATE OR REPLACE FUNCTION private.settle_driver_cash(p_driver_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_amount numeric;
begin
  if not is_admin() then raise exception 'admin_only'; end if;

  select cash_held into v_amount
    from drivers
   where id = p_driver_id
   for update;

  if not found then raise exception 'driver_not_found'; end if;
  if coalesce(v_amount, 0) <= 0 then return; end if;

  insert into driver_settlements (driver_id, kind, amount)
  values (p_driver_id, 'cash_remitted', v_amount);

  update drivers set cash_held = 0 where id = p_driver_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.settle_driver_earnings(p_driver_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_amount numeric;
begin
  if not is_admin() then raise exception 'admin_only'; end if;

  -- The driver row is the per-driver settlement lock. Concurrent requests for
  -- the same driver serialize before either can calculate unpaid earnings.
  perform 1 from drivers where id = p_driver_id for update;
  if not found then raise exception 'driver_not_found'; end if;

  select coalesce(sum(driver_earning), 0) into v_amount
    from driver_earnings
   where driver_id = p_driver_id and not paid;

  if v_amount <= 0 then return; end if;

  update driver_earnings
     set paid = true, paid_at = now()
   where driver_id = p_driver_id and not paid;

  insert into driver_settlements (driver_id, kind, amount)
  values (p_driver_id, 'earnings_paid', v_amount);

  update settlement_requests
     set status = 'fulfilled', resolved_at = now()
   where driver_id = p_driver_id and status = 'pending';
end;
$function$

CREATE OR REPLACE FUNCTION private.staff_create_pickup_order(p_restaurant_id integer, p_customer_name text, p_customer_phone text, p_compound_id integer, p_unit_number text, p_address_notes text DEFAULT ''::text, p_collect_amount numeric DEFAULT 0, p_request_notes text DEFAULT ''::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_fee numeric; v_km numeric; v_sla int; v_prep int; v_buffer int;
  v_ready timestamptz; v_dispatch timestamptz;
  v_vendor_type text; v_vendor_name text; v_total numeric;
  v_pct numeric; v_service numeric; v_threshold numeric; v_deposit_advice numeric;
  v_order_id int; v_token uuid; v_actor text;
begin
  if is_admin() then v_actor := 'admin';
  elsif is_supervisor() then v_actor := 'supervisor';
  else raise exception 'admin_only';
  end if;

  if coalesce(trim(p_customer_name),'') = '' or coalesce(trim(p_customer_phone),'') = ''
     or coalesce(trim(p_unit_number),'') = '' then
    raise exception 'missing_customer_details';
  end if;
  if p_compound_id is null then raise exception 'compound_id_required'; end if;
  if coalesce(p_collect_amount, 0) < 0 then raise exception 'invalid_collect_amount'; end if;

  select vendor_type, name, coalesce(prep_minutes, 15)
    into v_vendor_type, v_vendor_name, v_prep
    from restaurants where id = p_restaurant_id and not archived;
  if v_vendor_name is null then raise exception 'restaurant_not_found'; end if;

  -- The supervisor's remit stops at the restaurants, same boundary as
  -- supervisor_may_touch_order().
  if v_actor = 'supervisor' and coalesce(v_vendor_type, 'restaurant') <> 'restaurant' then
    raise exception 'not_authorized';
  end if;

  select distance_km, delivery_fee into v_km, v_fee from compounds where id = p_compound_id;
  if v_fee is null then raise exception 'compound_missing_fee'; end if;
  v_sla := sla_minutes_for(p_restaurant_id, p_compound_id);

  select coalesce((select value::int from settings where key = 'travel_buffer_minutes'), 10) into v_buffer;
  v_ready := now() + make_interval(mins => v_prep);
  v_dispatch := greatest(now(), v_ready - make_interval(mins => v_buffer));

  -- Same source, same base and same rounding as place_order.
  select coalesce((select value::numeric from settings where key = 'service_fee_percent'), 0) into v_pct;
  v_service := round(coalesce(p_collect_amount,0) * v_pct / 100.0);

  -- The driver collects the food price, the delivery fee AND the service fee at
  -- the door; only the food half is owed back to the vendor. subtotal carries
  -- the vendor's money so the earnings and cash screens keep working off the
  -- same columns they always have.
  v_total := v_fee + coalesce(p_collect_amount, 0) + v_service;

  select coalesce((select value::numeric from settings where key = 'cod_deposit_threshold_egp'), 300)
    into v_threshold;
  v_deposit_advice := case when v_total > v_threshold then ceil(v_total * 0.5) else null end;

  insert into orders (restaurant_id, customer_name, customer_phone, zone, unit_number,
                      address_notes, subtotal, delivery_fee, service_fee, total,
                      order_type, request_notes, pricing_status, kitchen_status,
                      payment_method, payment_mode, collect_amount,
                      compound_id, ready_at, dispatch_at, sla_minutes, status)
  values (p_restaurant_id, trim(p_customer_name), trim(p_customer_phone),
          (select name from compounds where id = p_compound_id),
          trim(p_unit_number), coalesce(p_address_notes,''),
          coalesce(p_collect_amount, 0), v_fee, v_service, v_total,
          'pickup_request',
          nullif(trim(coalesce(p_request_notes,'')),''),
          'n/a',
          -- Born ready: nobody presses "accept" on the vendor screen for an
          -- order the vendor phoned in, and driver_mark_picked_up requires
          -- kitchen_status = 'ready'.
          'ready',
          'cod', 'driver_pays', coalesce(p_collect_amount, 0),
          p_compound_id, v_ready, v_dispatch, v_sla, 'pending')
  returning id, public_token into v_order_id, v_token;

  insert into order_status_events (order_id, from_status, to_status, actor)
  values (v_order_id, null, 'pending', v_actor);

  return json_build_object('id', v_order_id, 'token', v_token,
                           'total', v_total, 'delivery_fee', v_fee,
                           'service_fee', v_service,
                           'collect_amount', coalesce(p_collect_amount, 0),
                           'deposit_advice', v_deposit_advice,
                           'deposit_threshold', v_threshold,
                           'vendor', v_vendor_name);
end $function$

CREATE OR REPLACE FUNCTION private.staff_vendor_open_states()
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or not (public.is_admin() or public.is_supervisor()) then
    raise exception 'not_authorized';
  end if;

  return (
    select coalesce(json_agg(json_build_object(
             'id',           r.id,
             'is_open',      public.vendor_is_open_now(r.id),
             'next_open_at', public.vendor_next_open_at(r.id),
             'closed_until', r.closed_until,
             'has_hours',    exists (
               select 1 from public.vendor_hours vh where vh.restaurant_id = r.id
             )
           )), '[]'::json)
    from public.restaurants r
    where not r.archived
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.submit_complaint(p_token uuid, p_description text, p_category text DEFAULT 'other'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order_id integer;
  v_driver_id integer;
  v_category text;
  v_description text;
  v_recent integer;
begin
  select id into v_order_id from orders where public_token = p_token;
  if v_order_id is null then raise exception 'order_not_found'; end if;

  v_description := nullif(btrim(coalesce(p_description, '')), '');
  if v_description is null or length(v_description) < 5 then
    raise exception 'complaint_too_short';
  end if;
  if length(v_description) > 2000 then raise exception 'complaint_too_long'; end if;

  -- Enough for separate item, quality and delivery problems without allowing a
  -- leaked order token to fill the operations queue indefinitely.
  select count(*) into v_recent
    from complaints
   where order_id = v_order_id
     and created_at > now() - interval '24 hours';
  if v_recent >= 5 then raise exception 'complaint_limit_reached'; end if;

  v_category := case
    when p_category in ('missing_item','wrong_item','driver_conduct','quality','other')
      then p_category
    else 'other'
  end;

  select driver_id into v_driver_id
    from driver_earnings where order_id = v_order_id limit 1;
  if v_driver_id is null then
    select driver_id into v_driver_id
      from delivery_assignments
     where order_id = v_order_id
     order by attempt_number desc
     limit 1;
  end if;

  insert into complaints (order_id, description, category, driver_id)
  values (v_order_id, v_description, v_category, v_driver_id);
end;
$function$

CREATE OR REPLACE FUNCTION private.submit_custom_order(p_restaurant_id integer, p_customer_name text, p_customer_phone text, p_zone text, p_unit_number text, p_address_notes text, p_delivery_fee numeric, p_request_items json, p_request_notes text, p_compound_id integer DEFAULT NULL::integer, p_session_token uuid DEFAULT NULL::uuid, p_slot_id integer DEFAULT NULL::integer, p_scheduled_date date DEFAULT NULL::date, p_prescription_path text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order_id int; v_token uuid; v_prep int; v_buffer int; v_ready timestamptz; v_dispatch timestamptz;
  v_mode text; v_fee numeric; v_km numeric; v_sla int; v_customer_id int;
  v_slot delivery_slots%rowtype; v_used int; v_rx text; v_item_count int;
begin
  if coalesce(trim(p_customer_name),'') = '' or coalesce(trim(p_customer_phone),'') = ''
     or coalesce(trim(p_zone),'') = '' or coalesce(trim(p_unit_number),'') = '' then
    raise exception 'missing_customer_details';
  end if;
  if is_banned(p_customer_phone) then
    raise exception 'account_blocked';
  end if;

  if p_session_token is not null then
    select cs.customer_id into v_customer_id
      from customer_sessions cs where cs.token = p_session_token and cs.expires_at > now();
  end if;

  select order_mode, coalesce(prep_minutes, 20) into v_mode, v_prep
    from restaurants where id = p_restaurant_id;
  if v_mode is distinct from 'custom_request' then raise exception 'not_a_custom_order_vendor'; end if;
  -- Opening hours. Same predicate every other order path uses.
  if not vendor_is_open_now(p_restaurant_id) then raise exception 'restaurant_closed'; end if;

  if p_compound_id is null then raise exception 'compound_id_required'; end if;
  select distance_km, delivery_fee into v_km, v_fee from compounds where id = p_compound_id;
  if v_km is null then raise exception 'compound_missing_distance'; end if;
  if v_fee is null then raise exception 'compound_missing_fee'; end if;
  v_sla := sla_minutes_for(p_restaurant_id, p_compound_id);

  v_rx := nullif(btrim(coalesce(p_prescription_path, '')), '');
  if v_rx is not null and v_rx !~ '^rx-[A-Za-z0-9_-]{6,60}\.(jpg|jpeg|png|webp|avif)$' then
    raise exception 'invalid_prescription_path';
  end if;

  v_item_count := coalesce(json_array_length(coalesce(p_request_items, '[]'::json)), 0);
  if v_item_count = 0 and v_rx is null then raise exception 'empty_order'; end if;

  select coalesce((select value::int from settings where key = 'travel_buffer_minutes'), 10) into v_buffer;

  if p_slot_id is not null then
    select * into v_slot from delivery_slots where id = p_slot_id and restaurant_id = p_restaurant_id for update;
    if not found or not v_slot.active then raise exception 'slot_unavailable'; end if;

    select count(*) into v_used from orders
      where slot_id = p_slot_id and scheduled_date = p_scheduled_date
        and status <> 'Cancelled';
    if v_used >= v_slot.capacity then raise exception 'slot_full'; end if;

    v_ready := (p_scheduled_date + v_slot.start_time) at time zone 'Africa/Cairo';
    v_dispatch := v_ready - make_interval(mins => v_buffer);
  else
    v_ready := now() + make_interval(mins => v_prep);
    v_dispatch := greatest(now(), v_ready - make_interval(mins => v_buffer));
  end if;

  insert into orders (restaurant_id, customer_name, customer_phone, zone, unit_number,
                      address_notes, subtotal, delivery_fee, total,
                      order_type, request_items, request_notes, pricing_status, status,
                      ready_at, dispatch_at, slot_id, scheduled_date, compound_id, sla_minutes,
                      customer_id, prescription_path)
  values (p_restaurant_id, trim(p_customer_name), trim(p_customer_phone), p_zone,
          trim(p_unit_number), coalesce(p_address_notes,''), 0, v_fee, v_fee,
          'custom_request', coalesce(p_request_items::jsonb, '[]'::jsonb),
          coalesce(p_request_notes,''), 'pending_quote', 'awaiting_quote',
          v_ready, v_dispatch, p_slot_id, p_scheduled_date, p_compound_id, v_sla,
          v_customer_id, v_rx)
  returning id, public_token into v_order_id, v_token;

  return json_build_object('id', v_order_id, 'token', v_token);
end; $function$

CREATE OR REPLACE FUNCTION private.submit_rating(p_token uuid, p_driver_rating integer DEFAULT NULL::integer, p_restaurant_rating integer DEFAULT NULL::integer, p_comment text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order_id integer;
  v_driver_id integer;
  v_restaurant_id integer;
  v_status text;
  v_comment text;
  v_customer_auth_user_id uuid;
  v_delivered_at timestamptz;
  v_rating_exists boolean;
  v_is_owner boolean;
begin
  if p_driver_rating is null and p_restaurant_rating is null then
    raise exception 'rating_required';
  end if;
  if p_driver_rating is not null and p_driver_rating not between 1 and 5 then
    raise exception 'invalid_driver_rating';
  end if;
  if p_restaurant_rating is not null and p_restaurant_rating not between 1 and 5 then
    raise exception 'invalid_restaurant_rating';
  end if;

  v_comment := btrim(coalesce(p_comment, ''));
  if length(v_comment) > 1000 then raise exception 'comment_too_long'; end if;

  -- Serialise the first submission and any owner revision on the order row.
  select o.id,
         o.restaurant_id,
         o.status,
         c.auth_user_id,
         delivered.delivered_at,
         exists (
           select 1 from public.order_ratings r where r.order_id = o.id
         )
    into v_order_id,
         v_restaurant_id,
         v_status,
         v_customer_auth_user_id,
         v_delivered_at,
         v_rating_exists
    from public.orders o
    left join public.customers c on c.id = o.customer_id
    left join lateral (
      select da.delivered_at
        from public.delivery_assignments da
       where da.order_id = o.id
         and da.status = 'Delivered'
       order by da.attempt_number desc
       limit 1
    ) delivered on true
   where o.public_token = p_token
   for update of o;

  if v_order_id is null then raise exception 'order_not_found'; end if;
  if v_status <> 'Delivered' then raise exception 'order_not_delivered'; end if;
  if v_delivered_at is null
     or v_delivered_at < now() - interval '30 days' then
    raise exception 'rating_window_closed';
  end if;

  v_is_owner := auth.uid() is not null
                and auth.uid() = v_customer_auth_user_id;

  if v_rating_exists and not v_is_owner then
    raise exception 'rating_already_submitted';
  end if;

  select da.driver_id into v_driver_id
    from public.delivery_assignments da
   where da.order_id = v_order_id and da.status = 'Delivered'
   order by da.attempt_number desc
   limit 1;

  insert into public.order_ratings (
    order_id,
    driver_rating,
    restaurant_rating,
    comment
  )
  values (
    v_order_id,
    p_driver_rating,
    p_restaurant_rating,
    v_comment
  )
  on conflict (order_id) do update set
    driver_rating = coalesce(excluded.driver_rating, order_ratings.driver_rating),
    restaurant_rating = coalesce(excluded.restaurant_rating, order_ratings.restaurant_rating),
    comment = excluded.comment;

  if p_driver_rating is not null and v_driver_id is not null then
    update public.drivers set rating = (
      select round(avg(r.driver_rating)::numeric, 1)
        from public.order_ratings r
        join public.delivery_assignments da2 on da2.order_id = r.order_id
       where da2.driver_id = v_driver_id and r.driver_rating is not null
    ) where id = v_driver_id;
  end if;

  if p_restaurant_rating is not null then
    update public.restaurants set rating = (
      select round(avg(r.restaurant_rating)::numeric, 1)
        from public.order_ratings r
        join public.orders o2 on o2.id = r.order_id
       where o2.restaurant_id = v_restaurant_id and r.restaurant_rating is not null
    ) where id = v_restaurant_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.submit_tip(p_token uuid, p_amount numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order_id integer;
  v_driver_id integer;
  v_status text;
  v_instapay text;
begin
  if p_amount is null or p_amount <= 0 or p_amount > 1000 then
    raise exception 'invalid_amount';
  end if;

  select o.id, o.status
    into v_order_id, v_status
    from public.orders o
   where o.public_token = p_token;
  if v_order_id is null then raise exception 'order_not_found'; end if;
  if v_status <> 'Delivered' then raise exception 'order_not_delivered'; end if;

  select da.driver_id, coalesce(d.instapay_number, d.phone)
    into v_driver_id, v_instapay
    from public.delivery_assignments da
    join public.drivers d on d.id = da.driver_id
   where da.order_id = v_order_id
     and da.status = 'Delivered'
   order by da.attempt_number desc
   limit 1;
  if v_driver_id is null then raise exception 'no_driver_on_this_order'; end if;
  if nullif(btrim(coalesce(v_instapay, '')), '') is null then
    raise exception 'driver_instapay_unavailable';
  end if;

  insert into public.driver_tips (order_id, driver_id, amount, status)
  values (v_order_id, v_driver_id, p_amount, 'reported')
  on conflict (order_id) do nothing;
end;
$function$

CREATE OR REPLACE FUNCTION private.switch_to_cash(p_token uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_o orders%rowtype;
  v_net numeric; v_threshold numeric; v_deposit numeric; v_status text;
begin
  select * into v_o from orders where public_token = p_token for update;
  if not found then raise exception 'order_not_found'; end if;

  if v_o.status <> 'awaiting_payment' then raise exception 'wrong_stage'; end if;
  if coalesce(v_o.payment_method, 'cod') = 'cod' then raise exception 'already_cash'; end if;
  if v_o.instapay_claimed_at is not null then raise exception 'payment_already_claimed'; end if;

  if exists (select 1 from delivery_assignments da
              where da.order_id = v_o.id
                and da.status in ('Offered','Accepted','Picked_Up','Out_for_Delivery')) then
    raise exception 'already_assigned';
  end if;

  -- orders.total IS the net total. Do not subtract wallet_used again.
  v_net := coalesce(v_o.total, 0);
  select coalesce((select value::numeric from settings where key = 'cod_deposit_threshold_egp'), 300)
    into v_threshold;

  v_deposit := case when v_net > v_threshold then ceil(v_net * 0.5) else null end;

  v_status := case
    when v_deposit is not null then 'awaiting_payment'
    when v_o.dispatch_at is not null and v_o.dispatch_at > now() then 'Scheduled'
    else 'pending'
  end;

  update orders
     set payment_method        = 'cod',
         online_payment_status = null,
         cod_deposit_amount    = v_deposit,
         status                = v_status
   where id = v_o.id;

  insert into order_status_events (order_id, from_status, to_status, actor)
  values (v_o.id, v_o.status, v_status, 'customer');

  return json_build_object('status', v_status, 'deposit_required', v_deposit, 'total', v_o.total);
end $function$

CREATE OR REPLACE FUNCTION private.update_my_customer_name(p_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id int; v_name text;
begin
  v_id := my_customer_id();
  if v_id is null then raise exception 'not_logged_in'; end if;

  v_name := nullif(btrim(coalesce(p_name, '')), '');
  if v_name is null then raise exception 'name_required'; end if;
  -- A driver has to read this off a phone at a door. Two characters is not a
  -- name, and 60 is more than any label can show.
  if length(v_name) < 2 or length(v_name) > 60 then raise exception 'invalid_name'; end if;

  update customers set name = v_name where id = v_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.vendor_accept_order(p_order_id integer, p_prep_minutes integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_slot_id int; v_buffer int; v_ready timestamptz; v_dispatch timestamptz;
begin
  if not (
    exists (select 1 from orders where id = p_order_id and restaurant_id = my_restaurant_id())
    or supervisor_may_touch_order(p_order_id)
  ) then
    raise exception 'not_your_order';
  end if;

  if (select coalesce(pricing_status, 'n/a') from orders where id = p_order_id) = 'pending_quote' then
    raise exception 'order_not_priced';
  end if;

  select slot_id into v_slot_id from orders where id = p_order_id;

  if v_slot_id is null and p_prep_minutes is not null then
    if p_prep_minutes not in (15, 20, 30) then raise exception 'invalid_prep_minutes'; end if;
    select coalesce((select value::int from settings where key = 'travel_buffer_minutes'), 10) into v_buffer;
    v_ready := now() + make_interval(mins => p_prep_minutes);
    v_dispatch := greatest(now(), v_ready - make_interval(mins => v_buffer));
    update orders set kitchen_status = 'preparing', vendor_accepted_at = now(),
      ready_at = v_ready, dispatch_at = v_dispatch
    where id = p_order_id;
  else
    update orders set kitchen_status = 'preparing', vendor_accepted_at = now() where id = p_order_id;
  end if;
end $function$

CREATE OR REPLACE FUNCTION private.vendor_delay(p_order_id integer, p_minutes integer DEFAULT 10)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_count int;
begin
  if not exists (select 1 from orders where id = p_order_id
                 and restaurant_id = my_restaurant_id()) then
    raise exception 'not_your_order';
  end if;

  select delay_count into v_count from orders where id = p_order_id;
  if v_count >= 3 then
    raise exception 'delay_limit_reached';
  end if;

  update orders
  set ready_at = coalesce(ready_at, now()) + make_interval(mins => p_minutes),
      dispatch_at = coalesce(dispatch_at, now()) + make_interval(mins => p_minutes),
      delay_count = delay_count + 1
  where id = p_order_id;
end; $function$

CREATE OR REPLACE FUNCTION private.vendor_ready(p_order_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not (
    exists (select 1 from orders where id = p_order_id and restaurant_id = my_restaurant_id())
    or supervisor_may_touch_order(p_order_id)
  ) then
    raise exception 'not_your_order';
  end if;
  if (select coalesce(pricing_status, 'n/a') from orders where id = p_order_id) = 'pending_quote' then
    raise exception 'order_not_priced';
  end if;
  update orders set kitchen_status = 'ready', ready_at = now(), dispatch_at = now()
  where id = p_order_id;
end $function$

CREATE OR REPLACE FUNCTION private.vendor_set_item_availability(p_item_id integer, p_available boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rid int;
begin
  select restaurant_id into v_rid from menu_items where id = p_item_id;
  if v_rid is null then raise exception 'item_not_found'; end if;
  if not coalesce(is_admin() or my_restaurant_id() = v_rid, false) then
    raise exception 'not_authorized';
  end if;
  update menu_items set available = p_available where id = p_item_id;
end; $function$

CREATE OR REPLACE FUNCTION private.vendor_set_open(p_open boolean)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rid int; v_next timestamptz;
begin
  v_rid := my_restaurant_id();
  if v_rid is null then raise exception 'not_a_vendor'; end if;
  if p_open is null then raise exception 'invalid_state'; end if;

  if p_open then
    update restaurants set closed_until = null, is_open = true where id = v_rid;
    return null;
  end if;

  -- Closing sets an EXPIRY, not a flag. The fryer is broken now; it will not be
  -- broken forever, and nobody should have to remember to undo this. Without an
  -- expiry a vendor closes at 11pm on Thursday and is still closed on Sunday --
  -- the exact failure this feature exists to end.
  v_next := vendor_next_open_at(v_rid);

  -- No hours configured, so there is no next opening to expire at. Fall back to
  -- the end of the Cairo day: still self-clearing, still bounded, and it matches
  -- what «اقفل دلوقتي» means to someone shutting up shop for the night.
  if v_next is null then
    v_next := (((now() at time zone 'Africa/Cairo')::date + 1)::timestamp)
              at time zone 'Africa/Cairo';
  end if;

  update restaurants set closed_until = v_next, is_open = false where id = v_rid;
  return v_next;
end $function$

CREATE OR REPLACE FUNCTION public.admin_set_vendor_slots(p_restaurant_id integer, p_enabled boolean, p_auth_user_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r boolean;
begin
  perform set_config('request.jwt.claim.sub', p_auth_user_id::text, true);
  select private.admin_set_vendor_slots(p_restaurant_id, p_enabled) into r;
  return r;
end $function$

CREATE OR REPLACE FUNCTION public.check_and_award_shift_bonus(p_driver_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_today date; v_count int;
  v_t1_orders int; v_t1_amount numeric; v_t2_orders int; v_t2_amount numeric; v_t3_orders int; v_t3_amount numeric;
  v_tier int; v_amount numeric; v_existing_tier int;
begin
  v_today := (now() at time zone 'Africa/Cairo')::date;

  select count(*) into v_count from driver_earnings
    where driver_id = p_driver_id and (created_at at time zone 'Africa/Cairo')::date = v_today;

  select coalesce((select value::int from settings where key='driver_bonus_tier1_orders'), 24) into v_t1_orders;
  select coalesce((select value::numeric from settings where key='driver_bonus_tier1_amount'), 100) into v_t1_amount;
  select coalesce((select value::int from settings where key='driver_bonus_tier2_orders'), 30) into v_t2_orders;
  select coalesce((select value::numeric from settings where key='driver_bonus_tier2_amount'), 150) into v_t2_amount;
  select coalesce((select value::int from settings where key='driver_bonus_tier3_orders'), 38) into v_t3_orders;
  select coalesce((select value::numeric from settings where key='driver_bonus_tier3_amount'), 200) into v_t3_amount;

  if v_count >= v_t3_orders then v_tier := 3; v_amount := v_t3_amount;
  elsif v_count >= v_t2_orders then v_tier := 2; v_amount := v_t2_amount;
  elsif v_count >= v_t1_orders then v_tier := 1; v_amount := v_t1_amount;
  else return;
  end if;

  select tier_reached into v_existing_tier from driver_shift_bonuses
    where driver_id = p_driver_id and bonus_date = v_today;

  if v_existing_tier is null then
    insert into driver_shift_bonuses (driver_id, bonus_date, tier_reached, orders_count, bonus_amount)
    values (p_driver_id, v_today, v_tier, v_count, v_amount);
  elsif v_tier > v_existing_tier then
    update driver_shift_bonuses set tier_reached = v_tier, orders_count = v_count, bonus_amount = v_amount
    where driver_id = p_driver_id and bonus_date = v_today;
  end if;
end; $function$

CREATE OR REPLACE FUNCTION public.check_rate_limit(p_bucket text, p_max integer, p_window interval)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  delete from rate_limit_log where called_at < now() - greatest(p_window, interval '1 hour');
  if (select count(*) from rate_limit_log where bucket = p_bucket and called_at > now() - p_window) >= p_max then
    raise exception 'rate_limited';
  end if;
  insert into rate_limit_log (bucket) values (p_bucket);
end;
$function$

CREATE OR REPLACE FUNCTION public.current_actor_label()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then return 'system'; end if;
  if is_admin() then return 'admin'; end if;
  if my_driver_id() is not null then return 'driver'; end if;
  if my_restaurant_id() is not null then return 'vendor'; end if;
  if my_customer_id() is not null then return 'customer'; end if;
  return 'authenticated';
exception when others then
  return 'system';
end;
$function$

CREATE OR REPLACE FUNCTION public.driver_can_take_order(p_driver_id integer, p_order_id integer)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_active_count int; v_existing_direction text; v_new_direction text;
  v_vendor_type text; v_vehicle text; v_subtotal numeric; v_pricing text; v_threshold numeric;
begin
  select c.direction into v_new_direction
  from orders o left join compounds c on c.id = o.compound_id where o.id = p_order_id;

  select count(*), (array_agg(c.direction))[1] into v_active_count, v_existing_direction
  from delivery_assignments da
    join orders o2 on o2.id = da.order_id
    left join compounds c on c.id = o2.compound_id
  where da.driver_id = p_driver_id
    and da.status in ('Accepted','Picked_Up','Out_for_Delivery');

  if v_active_count >= 3 then return false; end if;
  if v_active_count > 0 and v_existing_direction is not null and v_new_direction is not null
     and v_existing_direction <> v_new_direction then return false; end if;

  -- Vehicle rule, previously only in available_orders and claim_order.
  select r.vendor_type, o.subtotal, coalesce(o.pricing_status, 'n/a')
    into v_vendor_type, v_subtotal, v_pricing
  from orders o join restaurants r on r.id = o.restaurant_id where o.id = p_order_id;

  if v_vendor_type = 'supermarket' then
    select coalesce((select value::numeric from settings where key = 'van_required_subtotal_egp'), 800)
      into v_threshold;
    if v_pricing = 'pending_quote' or coalesce(v_subtotal, 0) >= v_threshold then
      select vehicle_type into v_vehicle from drivers where id = p_driver_id;
      if coalesce(v_vehicle, '') <> 'van' then return false; end if;
    end if;
  end if;

  return true;
end $function$

CREATE OR REPLACE FUNCTION public.last_address_for_phone(p_phone text, p_session_token uuid, p_auth_user_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_phone text;
begin
  if p_session_token is not null then
    select c.phone into v_phone
      from customer_sessions cs join customers c on c.id = cs.customer_id
     where cs.token = p_session_token and cs.expires_at > now();
  end if;
  if v_phone is null and p_auth_user_id is not null then
    select c.phone into v_phone from customers c
     where c.auth_user_id = p_auth_user_id and coalesce(c.phone, '') <> '' limit 1;
  end if;
  if v_phone is null then return null; end if;
  if normalize_phone(v_phone) <> normalize_phone(p_phone) then return null; end if;
  return (
    select row_to_json(x) from (
      select o.zone, o.compound_id, o.unit_number, o.address_notes, o.customer_name
        from orders o
       where normalize_phone(o.customer_phone) = normalize_phone(v_phone)
       order by o.created_at desc limit 1
    ) x
  );
end
$function$

CREATE OR REPLACE FUNCTION public.my_last_request(p_restaurant_id integer, p_session_token uuid, p_auth_user_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_phone text;
begin
  if p_session_token is not null then
    select c.phone into v_phone
      from customer_sessions cs join customers c on c.id = cs.customer_id
     where cs.token = p_session_token and cs.expires_at > now();
  end if;
  if v_phone is null and p_auth_user_id is not null then
    select c.phone into v_phone from customers c
     where c.auth_user_id = p_auth_user_id and coalesce(c.phone, '') <> '' limit 1;
  end if;
  if v_phone is null then return 'null'::json; end if;
  return coalesce((
    select row_to_json(x) from (
      select o.id, o.created_at, o.request_items
        from orders o
       where o.restaurant_id = p_restaurant_id
         and normalize_phone(o.customer_phone) = normalize_phone(v_phone)
         and o.order_type = 'custom_request'
         and jsonb_array_length(coalesce(o.request_items,'[]'::jsonb)) > 0
       order by o.created_at desc limit 1
    ) x
  ), 'null'::json);
end
$function$

CREATE OR REPLACE FUNCTION public.my_orders(p_phone text, p_session_token uuid, p_auth_user_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_phone text;
begin
  if p_session_token is not null then
    select c.phone into v_phone
      from customer_sessions cs join customers c on c.id = cs.customer_id
     where cs.token = p_session_token and cs.expires_at > now();
  end if;
  if v_phone is null and p_auth_user_id is not null then
    select c.phone into v_phone from customers c
     where c.auth_user_id = p_auth_user_id and coalesce(c.phone, '') <> '' limit 1;
  end if;
  if v_phone is null then raise exception 'not_logged_in'; end if;
  v_phone := normalize_phone(v_phone);
  return (
    select coalesce(json_agg(row_to_json(x)), '[]'::json)
      from (
        select o.id, o.public_token, o.total, o.status, o.created_at,
               coalesce(o.pricing_status, 'n/a') as pricing_status,
               r.name as restaurant_name
          from orders o join restaurants r on r.id = o.restaurant_id
         where normalize_phone(o.customer_phone) = v_phone
           and o.created_at > now() - interval '30 days'
         order by o.id desc limit 20
      ) x
  );
end
$function$

CREATE OR REPLACE FUNCTION public.notify_admin(p_title text, p_body text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_secret text; v_targets jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object('token', pt.token, 'platform', pt.platform)), '[]'::jsonb)
    into v_targets
    from push_tokens pt join profiles p on p.id = pt.profile_id
   where p.role in ('admin', 'supervisor');
  if jsonb_array_length(v_targets) = 0 then return; end if;
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'push_webhook_secret';
  perform net.http_post(
    url := 'https://pqpnwxyevrsipklzmwex.supabase.co/functions/v1/send-push',
    headers := jsonb_build_object('Content-Type','application/json','x-webhook-secret', coalesce(v_secret,'')),
    body := jsonb_build_object('tokens', v_targets, 'title', p_title, 'body', p_body, 'data', p_data)
  );
exception when others then null;
end $function$

CREATE OR REPLACE FUNCTION public.notify_admin_new_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_vendor text; v_compound text; v_title text; v_body text;
begin
  select r.name into v_vendor from restaurants r where r.id = new.restaurant_id;
  select c.name into v_compound from compounds c where c.id = new.compound_id;

  if new.order_type = 'custom_request' or new.pricing_status = 'pending_quote' then
    v_title := 'طلب مخصص محتاج تسعير 💰';
    v_body  := 'طلب #' || new.id || ' من ' || coalesce(v_vendor,'—')
               || ' — لازم تحدد السعر عشان يتنفذ';
  else
    v_title := 'طلب جديد 🔔';
    v_body  := 'طلب #' || new.id || ' — ' || coalesce(v_vendor,'—')
               || ' → ' || coalesce(v_compound, coalesce(new.zone,'—'))
               || ' — ' || coalesce(new.total,0)::text || ' ج.م';
  end if;

  perform notify_admin(v_title, v_body,
    jsonb_build_object('order_id', new.id, 'kind', 'new_order'));
  return new;
exception when others then
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_admin_order_trouble()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tokens jsonb;
begin
  if new.status = 'Cancelled' and old.status is distinct from 'Cancelled' then
    perform notify_admin('طلب اتلغى ❌',
      'طلب #' || new.id || ' اتلغى — ' || coalesce(new.cancel_reason,'من غير سبب'),
      jsonb_build_object('order_id', new.id, 'kind', 'cancelled'));

    -- THE KITCHEN. Only if they had taken it on.
    if coalesce(old.kitchen_status, 'new') <> 'new' or old.vendor_accepted_at is not null then
      select coalesce(jsonb_agg(jsonb_build_object('token', pt.token, 'platform', pt.platform)), '[]'::jsonb)
        into v_tokens
        from push_tokens pt join profiles p on p.id = pt.profile_id
       where p.role = 'vendor' and p.restaurant_id = new.restaurant_id;
      if jsonb_array_length(v_tokens) > 0 then
        perform push_send(v_tokens, 'وقّف التحضير ⛔',
          'طلب #' || new.id || ' اتلغى — بطّل تحضيره',
          jsonb_build_object('order_id', new.id, 'kind', 'vendor_cancelled'));
      end if;
    end if;

  elsif new.pricing_status = 'pending_quote'
        and old.pricing_status is distinct from 'pending_quote' then
    perform notify_admin('طلب محتاج تسعير 💰',
      'طلب #' || new.id || ' مستني السعر',
      jsonb_build_object('order_id', new.id, 'kind', 'pending_quote'));
  end if;
  return new;
exception when others then
  return new;
end;
$function$

