CREATE OR REPLACE FUNCTION public.place_order(p_restaurant_id integer, p_customer_name text, p_customer_phone text, p_zone text, p_unit_number text, p_address_notes text, p_delivery_fee numeric, p_items json, p_slot_id integer DEFAULT NULL::integer, p_scheduled_date date DEFAULT NULL::date, p_compound_id integer DEFAULT NULL::integer, p_payment_method text DEFAULT 'cod'::text, p_use_wallet boolean DEFAULT false, p_session_token uuid DEFAULT NULL::uuid, p_customer_note text DEFAULT NULL::text, p_rate_key text DEFAULT NULL::text, p_auth_user_id uuid DEFAULT NULL::uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_phone text; v_bucket text; v_recent integer; v_result json;
begin
  v_phone := normalize_phone(p_customer_phone);
  if length(btrim(coalesce(p_customer_name, ''))) not between 2 and 100 then raise exception 'invalid_customer_name'; end if;
  if v_phone is null or v_phone !~ '^1[0-25][0-9]{8}$' then raise exception 'invalid_phone'; end if;
  if length(btrim(coalesce(p_zone, ''))) not between 1 and 120 then raise exception 'invalid_zone'; end if;
  if length(btrim(coalesce(p_unit_number, ''))) not between 1 and 100 then raise exception 'invalid_unit_number'; end if;
  if length(coalesce(p_address_notes, '')) > 1000 or length(coalesce(p_customer_note, '')) > 1000 then raise exception 'notes_too_long'; end if;
  if p_items is null or json_typeof(p_items) <> 'array' then raise exception 'invalid_items'; end if;
  if json_array_length(p_items) not between 1 and 50 then raise exception 'invalid_item_count'; end if;
  if exists (select 1 from json_array_elements(p_items) item where
    not (coalesce(item->>'qty','') ~ '^[0-9]{1,3}$' and (item->>'qty')::numeric between 1 and 100)
  ) then raise exception 'invalid_item_quantity'; end if;
  if p_rate_key is null or p_rate_key !~ '^[0-9a-f]{64}$' then raise exception 'invalid_rate_key'; end if;

  v_bucket := 'order-hmac:' || p_rate_key;
  perform pg_advisory_xact_lock(hashtextextended(v_bucket, 0));
  select count(*) into v_recent from rate_limit_log where bucket = v_bucket and called_at > now() - interval '15 minutes';
  if v_recent >= 5 then raise exception 'order_rate_limit'; end if;
  select count(*) into v_recent from rate_limit_log where bucket = v_bucket and called_at > now() - interval '24 hours';
  if v_recent >= 20 then raise exception 'daily_order_limit'; end if;

  if p_auth_user_id is not null then
    perform set_config('request.jwt.claim.sub', p_auth_user_id::text, true);
  end if;
  v_result := private.place_order(
    p_restaurant_id,p_customer_name,v_phone,p_zone,p_unit_number,p_address_notes,
    p_delivery_fee,p_items,p_slot_id,p_scheduled_date,p_compound_id,p_payment_method,
    p_use_wallet,p_session_token,p_customer_note
  );
  insert into rate_limit_log(bucket) values(v_bucket);
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.push_send(p_targets jsonb, p_title text, p_body text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_secret text;
begin
  if p_targets is null or jsonb_array_length(p_targets) = 0 then return; end if;
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'push_webhook_secret';
  perform net.http_post(
    url := 'https://pqpnwxyevrsipklzmwex.supabase.co/functions/v1/send-push',
    headers := jsonb_build_object('Content-Type','application/json','x-webhook-secret', coalesce(v_secret,'')),
    body := jsonb_build_object('tokens', p_targets, 'title', p_title, 'body', p_body, 'data', p_data)
  );
exception when others then null;
end $function$

CREATE OR REPLACE FUNCTION public.record_push_result(p_token text, p_ok boolean, p_status integer, p_err_code text, p_title text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_profile uuid; v_platform text;
begin
  select profile_id, platform into v_profile, v_platform
    from push_tokens where token = p_token limit 1;

  insert into push_send_log (token_prefix, profile_id, platform, ok, status, err_code, title)
  values (left(p_token, 12) || '...', v_profile, v_platform, p_ok, p_status, p_err_code, p_title);

  if not p_ok and (p_err_code in ('UNREGISTERED','INVALID_ARGUMENT') or p_status = 404) then
    insert into dead_push_tokens (token, err_code) values (p_token, p_err_code)
      on conflict (token) do update set died_at = now(), err_code = excluded.err_code;

    delete from push_tokens where token = p_token;
    update orders set push_token = null where push_token = p_token;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_pickup(p_restaurant_id integer, p_customer_name text, p_customer_phone text, p_zone text, p_unit_number text, p_address_notes text, p_delivery_fee numeric, p_payment_mode text, p_collect_amount numeric, p_request_notes text, p_compound_id integer DEFAULT NULL::integer, p_session_token uuid DEFAULT NULL::uuid, p_rate_key text DEFAULT NULL::text, p_auth_user_id uuid DEFAULT NULL::uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_phone text; v_bucket text; v_recent integer; v_result json;
begin
  v_phone := normalize_phone(p_customer_phone);
  if p_auth_user_id is null or not exists (
    select 1 from profiles where id = p_auth_user_id and role = 'vendor' and restaurant_id = p_restaurant_id
  ) then raise exception 'not_your_restaurant'; end if;
  if length(btrim(coalesce(p_customer_name, ''))) not between 2 and 100 then raise exception 'invalid_customer_name'; end if;
  if v_phone is null or v_phone !~ '^1[0-25][0-9]{8}$' then raise exception 'invalid_phone'; end if;
  if length(btrim(coalesce(p_zone, ''))) not between 1 and 120 then raise exception 'invalid_zone'; end if;
  if length(btrim(coalesce(p_unit_number, ''))) not between 1 and 100 then raise exception 'invalid_unit_number'; end if;
  if length(coalesce(p_address_notes, '')) > 1000 or length(coalesce(p_request_notes, '')) > 2000 then raise exception 'notes_too_long'; end if;
  if p_collect_amount = 'NaN'::numeric or coalesce(p_collect_amount,0) < 0 or coalesce(p_collect_amount,0) > 1000000 then raise exception 'invalid_collect_amount'; end if;
  if p_rate_key is null or p_rate_key !~ '^[0-9a-f]{64}$' then raise exception 'invalid_rate_key'; end if;

  v_bucket := 'order-hmac:' || p_rate_key;
  perform pg_advisory_xact_lock(hashtextextended(v_bucket, 0));
  select count(*) into v_recent from rate_limit_log where bucket = v_bucket and called_at > now() - interval '15 minutes';
  if v_recent >= 5 then raise exception 'order_rate_limit'; end if;
  select count(*) into v_recent from rate_limit_log where bucket = v_bucket and called_at > now() - interval '24 hours';
  if v_recent >= 20 then raise exception 'daily_order_limit'; end if;

  v_result := private.request_pickup(
    p_restaurant_id,p_customer_name,v_phone,p_zone,p_unit_number,p_address_notes,
    p_delivery_fee,p_payment_mode,p_collect_amount,p_request_notes,p_compound_id,p_session_token
  );
  insert into rate_limit_log(bucket) values(v_bucket);
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.session_whoami(p_token uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_customer_id int; v_name text; v_phone text; v_expires timestamptz;
begin
  select cs.customer_id, cs.expires_at into v_customer_id, v_expires
    from customer_sessions cs where cs.token = p_token;
  if v_customer_id is null or v_expires < now() then return null; end if;

  update customer_sessions set last_used_at = now(), expires_at = now() + interval '180 days'
    where token = p_token;

  select name, phone into v_name, v_phone from customers where id = v_customer_id;
  return json_build_object('customer_id', v_customer_id, 'name', v_name, 'phone', v_phone);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_verified_customer_phone(p_auth_user_id uuid, p_phone text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_customer_id integer;
  v_phone text;
  v_owner integer;
  v_claimed integer;
begin
  if p_auth_user_id is null then raise exception 'not_logged_in'; end if;

  v_phone := normalize_phone(p_phone);
  if v_phone is null or v_phone !~ '^1[0-25][0-9]{8}$' then
    raise exception 'invalid_phone';
  end if;

  select id into v_customer_id
    from customers
   where auth_user_id = p_auth_user_id;
  if v_customer_id is null then raise exception 'customer_not_found'; end if;

  select id into v_owner from customers where phone = v_phone;
  if v_owner is not null and v_owner <> v_customer_id then
    raise exception 'phone_already_registered';
  end if;

  update customers set phone = v_phone where id = v_customer_id;

  update orders
     set customer_id = v_customer_id
   where customer_id is null
     and normalize_phone(customer_phone) = v_phone;
  get diagnostics v_claimed = row_count;

  return json_build_object(
    'customer_id', v_customer_id,
    'phone', v_phone,
    'claimed_orders', v_claimed
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_custom_order(p_restaurant_id integer, p_customer_name text, p_customer_phone text, p_zone text, p_unit_number text, p_address_notes text, p_delivery_fee numeric, p_request_items json, p_request_notes text, p_compound_id integer DEFAULT NULL::integer, p_session_token uuid DEFAULT NULL::uuid, p_slot_id integer DEFAULT NULL::integer, p_scheduled_date date DEFAULT NULL::date, p_prescription_path text DEFAULT NULL::text, p_rate_key text DEFAULT NULL::text, p_auth_user_id uuid DEFAULT NULL::uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_phone text; v_items json := coalesce(p_request_items,'[]'::json); v_bucket text; v_recent integer; v_result json;
begin
  v_phone := normalize_phone(p_customer_phone);
  if length(btrim(coalesce(p_customer_name, ''))) not between 2 and 100 then raise exception 'invalid_customer_name'; end if;
  if v_phone is null or v_phone !~ '^1[0-25][0-9]{8}$' then raise exception 'invalid_phone'; end if;
  if length(btrim(coalesce(p_zone, ''))) not between 1 and 120 then raise exception 'invalid_zone'; end if;
  if length(btrim(coalesce(p_unit_number, ''))) not between 1 and 100 then raise exception 'invalid_unit_number'; end if;
  if length(coalesce(p_address_notes, '')) > 1000 or length(coalesce(p_request_notes, '')) > 2000 then raise exception 'notes_too_long'; end if;
  if json_typeof(v_items) <> 'array' then raise exception 'invalid_items'; end if;
  if json_array_length(v_items) > 50 then raise exception 'invalid_item_count'; end if;
  if exists (select 1 from json_array_elements(v_items) item where json_typeof(item) <> 'object'
    or length(btrim(coalesce(item->>'name',''))) not between 1 and 200
    or not (coalesce(item->>'qty','') ~ '^[0-9]{1,3}$' and (item->>'qty')::numeric between 1 and 100)
  ) then raise exception 'invalid_item'; end if;
  if p_rate_key is null or p_rate_key !~ '^[0-9a-f]{64}$' then raise exception 'invalid_rate_key'; end if;

  v_bucket := 'order-hmac:' || p_rate_key;
  perform pg_advisory_xact_lock(hashtextextended(v_bucket, 0));
  select count(*) into v_recent from rate_limit_log where bucket = v_bucket and called_at > now() - interval '15 minutes';
  if v_recent >= 5 then raise exception 'order_rate_limit'; end if;
  select count(*) into v_recent from rate_limit_log where bucket = v_bucket and called_at > now() - interval '24 hours';
  if v_recent >= 20 then raise exception 'daily_order_limit'; end if;

  if p_auth_user_id is not null then perform set_config('request.jwt.claim.sub',p_auth_user_id::text,true); end if;
  v_result := private.submit_custom_order(
    p_restaurant_id,p_customer_name,v_phone,p_zone,p_unit_number,p_address_notes,
    p_delivery_fee,v_items,p_request_notes,p_compound_id,p_session_token,p_slot_id,
    p_scheduled_date,p_prescription_path
  );
  insert into rate_limit_log(bucket) values(v_bucket);
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.update_my_customer_phone(p_phone text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id int; v_phone text; v_owner int; v_claimed int;
begin
  v_id := my_customer_id();
  if v_id is null then raise exception 'not_logged_in'; end if;

  v_phone := normalize_phone(p_phone);
  -- 10 digits, leading 0 stripped; Egyptian mobile prefixes 010/011/012/015
  if v_phone is null or v_phone !~ '^1[0-25][0-9]{8}$' then
    raise exception 'invalid_phone';
  end if;

  select id into v_owner from customers where phone = v_phone;
  if v_owner is not null and v_owner <> v_id then
    raise exception 'phone_already_registered';
  end if;

  begin
    update customers set phone = v_phone where id = v_id;
  exception when unique_violation then
    raise exception 'phone_already_registered';
  end;

  -- Adopt this person's earlier guest orders.
  update orders
     set customer_id = v_id
   where customer_id is null
     and normalize_phone(customer_phone) = v_phone;
  get diagnostics v_claimed = row_count;

  if v_claimed > 0 then
    raise notice 'linked % guest order(s) to customer %', v_claimed, v_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.vendor_is_open_now(p_restaurant_id integer)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_until timestamptz; v_found boolean;
  v_now_cairo time; v_dow int; v_any int;
  v_o time; v_c time; v_closed boolean;
begin
  select closed_until, true into v_until, v_found
  from restaurants where id = p_restaurant_id and not archived;
  if not coalesce(v_found, false) then return false; end if;

  -- A live temporary close beats the schedule.
  if v_until is not null and v_until > now() then return false; end if;

  select count(*) into v_any from vendor_hours where restaurant_id = p_restaurant_id;
  -- No hours configured at all: open, exactly as the product behaved before
  -- hours existed. This is what stops the feature darkening live vendors.
  if v_any = 0 then return true; end if;

  v_now_cairo := (now() at time zone 'Africa/Cairo')::time;
  v_dow := extract(dow from (now() at time zone 'Africa/Cairo'))::int;

  -- Today's window.
  select opens_at, closes_at, closed into v_o, v_c, v_closed
  from vendor_hours where restaurant_id = p_restaurant_id and day_of_week = v_dow;
  if found and not coalesce(v_closed, false)
     and day_window_covers(v_now_cairo, v_o, v_c, false) then
    return true;
  end if;

  -- Yesterday's overnight tail. Thursday 10:00-03:00 is why 01:00 on Friday
  -- is open.
  select opens_at, closes_at, closed into v_o, v_c, v_closed
  from vendor_hours where restaurant_id = p_restaurant_id and day_of_week = (v_dow + 6) % 7;
  if found and not coalesce(v_closed, false)
     and day_window_covers(v_now_cairo, v_o, v_c, true) then
    return true;
  end if;

  return false;
end $function$

CREATE OR REPLACE FUNCTION public.vendor_next_open_at(p_restaurant_id integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_until timestamptz; v_any int; v_today date; v_dow int;
  v_o time; v_c time; v_closed boolean; v_cand timestamptz; v_i int;
begin
  select closed_until into v_until from restaurants
   where id = p_restaurant_id and not archived;

  select count(*) into v_any from vendor_hours where restaurant_id = p_restaurant_id;

  -- No hours: nothing to promise beyond an active temporary close.
  if v_any = 0 then
    return case when v_until is not null and v_until > now() then v_until else null end;
  end if;

  if vendor_is_open_now(p_restaurant_id) then return null; end if;

  v_today := (now() at time zone 'Africa/Cairo')::date;

  -- Today first, then the next seven days. Eight covers the case where the only
  -- trading day is the same weekday a week out.
  for v_i in 0..7 loop
    v_dow := extract(dow from (v_today + v_i))::int;

    select opens_at, closes_at, closed into v_o, v_c, v_closed
      from vendor_hours
     where restaurant_id = p_restaurant_id and day_of_week = v_dow;

    if found and not coalesce(v_closed, false) and v_o is not null then
      v_cand := ((v_today + v_i) + v_o) at time zone 'Africa/Cairo';
      if v_cand > now() then
        -- A temporary close can outlast the next scheduled opening.
        if v_until is not null and v_until > v_cand then return v_until; end if;
        return v_cand;
      end if;
    end if;
  end loop;

  -- Every day marked closed. Honest answer: we do not know.
  return case when v_until is not null and v_until > now() then v_until else null end;
end $function$

CREATE OR REPLACE FUNCTION public.wallet_balance_for_phone(p_phone text, p_session_token uuid, p_auth_user_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_phone text;
begin
  if p_session_token is not null then
    select c.phone into v_phone
      from customer_sessions cs join customers c on c.id = cs.customer_id
     where cs.token = p_session_token and cs.expires_at > now();
  end if;
  if v_phone is null and p_auth_user_id is not null then
    select c.phone into v_phone from customers c
     where c.auth_user_id = p_auth_user_id and coalesce(c.phone, '') <> '' limit 1;
  end if;
  if v_phone is null then return 0; end if;
  if normalize_phone(v_phone) <> normalize_phone(p_phone) then return 0; end if;
  return coalesce((select balance from customer_wallets where phone = normalize_phone(v_phone)), 0);
end
$function$
